WITH payload AS (SELECT $archive_payload$[{"id":"c0fe17b8-bd77-5c4a-87a7-3764615b2b8a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حد املسكر -عقوق والدة بالتهجم عليها ومحاولة ضربها -تهديد إخوته -مطالبة صاحب احلق اخلاص يف الدعوى العامة -التعزير مشروع يف كل معصية الحد فيها وال كفارة -التعزير بالسجن واجللد وأخذ التعهد عليه .","document_number":"34210183","case_number":"34210385","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/8","year":"1434","subject":"مسكر -شرب املسكر -حد املسكر -عقوق والدة بالتهجم عليها ومحاولة ضربها -تهديد إخوته -مطالبة صاحب احلق اخلاص يف الدعوى العامة -التعزير مشروع يف كل معصية الحد فيها وال كفارة -التعزير بالسجن واجللد وأخذ التعهد عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 34210183:‬تاريخه‪1434/5/8:‬هـ‬\n                   ‫رقم الدعوى‪34210385:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34237655:‬تاريخه‪1434/06/11:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر‪ -‬حــد املســكر ‪ -‬عقــوق والــدة بالتهجــم عليهــا‬\n‫ومحاولــة ضربهــا ‪ -‬تهديــد إخوتــه ‪ -‬مطالبــة صاحــب احلــق اخلــاص‬\n‫يف الدعــوى العامــة ‪ -‬التعزيــر مشــروع يف كل معصيــة الحــد فيهــا وال‬\n            ‫كفــارة ‪ -‬التعزيــر بالســجن واجللــد وأخــذ التعهــد عليــه ‪.‬‬\n\n\n\n‫‪ -1‬قولــه تعالــى‪( :‬وقضــى ربــك أن ال تعبــدوا إال إيــاه وبالوالديــن‬\n                                                                   ‫إحســانا)‪.‬‬\n‫‪ -2‬قولــه صلــى اهلل عليــه وســلم‪( :‬كل م ـ ـ ـ ـ ــسكر خمــر وكل خمــر‬\n                                                                     ‫حــرام ) ‪.‬‬\n‫‪ -3‬قولــه صلــى اهلل عليــه وســلم‪ ( :‬أال أخبركــم بأكبــر الكبائــر قلنــا‬\n‫بلــى يــا رســول اهلل قــال اإلشــراك بــاهلل وعقــوق الوالديــن وكان متــكأ‬\n                                      ‫فجلــس ثــم قــال أال وقــول الــزور )‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه لشــرب املســكر وعقــوق والدتــه‬\n‫بالتهجــم عليهــا ومحاولــة ضربهــا وتهديــده ألخواتــه وضــرب أخيــه ‪،‬‬\n‫وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر وتعزيــره‬\n‫لعقــوق والدتــه ومحاولــة ضربهــا وتهديــد إخوتــه وتشــديد العقوبــة لعظــم‬\n‫جرمــه ‪،‬حيــث ورد بــاغ للشــرطة مــن امــرأة بحضــور ابنهــا املدعــى عليــه‬\n                                                                                  ‫‪202‬‬\n\f      ‫إلــى املنــزل يف آخــر الليــل وهــو بحالــة غيــر طبيعيــة وتهجــم عليهــا وحــاول‬\n      ‫ضربهــا وضــرب إخوتــه وقــام بتهديدهــم وعنــد قيــام أحــد أبنائهــا بإبعــاده‬\n      ‫عنهــا قــام بضربــه ممــا تســبب يف إصابتــه وأفــادت أن املدعــى عليــه عــاق‬\n      ‫لهــا وبإثبــات حالــة املدعــى عليــه مــن قبــل الفرقــة القابضــة اتضــح أنــه‬\n      ‫بحالــة غيــر طبيعيــة وتفــوح منــه رائحــة كريهــة تشــبه رائحــة املســكر‬\n      ‫‪،‬وصــادق املدعــى عليــه علــى الدعــوى ‪،‬وحضــرت والــدة املدعــى عليــه‬\n      ‫تطلــب تأديبــه لعقوقــه وســبه ومحاولــة اعتدائــه عليهــا وعلــى إخوتــه‬\n      ‫‪،‬وتنــازل شــقيقه عنــه فيمــا حلقــه مــن إصابــات ‪،‬وبنــاء علــى مــا تقــدم‬\n      ‫حكمــت احملكمــة بجلــده ثمانــن جلــدة دفعــة واحــده حــد املســكر‬\n      ‫أمــام جمــع مــن النــاس وتعزيــره للحقــن العــام واخلــاص بجلــده ســتمائة‬\n      ‫جلــدة مفرقــة علــى اثنــي عشــر دفعــة وســجنه ســنة وأخــذ التعهــد عليــه‬\n      ‫بعــدم العــودة ‪،‬وقنعــت املدعيــة باحلكــم واعتــرض املدعــى عليــه واملدعي‬\n              ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬      ‫العــام بــدون الئحــة ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫باملدينة املنورة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n      ‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 34210385‬وتاريــخ ‪ 1434/05/06‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 341121165‬وتاريــخ ‪ 1434/05/06‬ه ـ ففــي‬\n      ‫يــوم األربعــاء املوافــق‪ 1434/05/08‬ه ـ افتتحــت اجللســة الســاعة ‪: 00‬‬\n      ‫‪ 11‬وفيهــا حضــر املدعــي العــام بهيئــة التحقيــق واالدعــاء العــام باملدينــة‬\n      ‫املنــورة ‪..........‬و أدعــى علــي احلاضــر معــه مبجلــس احلكــم ‪..........‬‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪.....‬قائــا يف حتريــر دعــواه إنــه بتاريــخ‬\n      ‫‪1434/4/10‬ه ـ أبلغــت املــرأة ‪.....‬أن ابنهــا املدعــى عليــه حضــر إلــى‬\n‫‪203‬‬\n\f‫املنــزل يف آخــر الليــل وهــو يف حالــة غيــر طبيعيــة وتهجــم عليهــا وحــاول‬\n‫ضربهــا وضــرب أخواتــه وقــام بتهديدهــم فقــام ابنهــا ‪.....‬مبحاولــة إبعــاده‬\n‫عنهــا فقــام بضربــه ممــا تســبب يف إصابتــه وأضافــت أن املدعــى عليــه‬\n‫عــاق لهــا وأنهــا قــد أبلغــت عنــه وتنازلــت عنــه لغلبــة شــفقة األم إال أنــه‬\n‫مــا زال علــى عقوقــه وحالــه مــن شــرب املســكر حتــى أضحــى خطــر ًا‬\n‫علــى األســرة كلهــا وبســماع أقــوال أخيــه‪.......... /‬البالــغ مــن العمــر (‪)21‬‬\n‫عامـ ًا أفــاد أن أخــاه املدعــى عليــه حضــر مــن خــارج املنــزل وتهجــم علــى‬\n‫والدتــه وحــاول ضربهــا وضــرب أخيــه وقــام بتهديدهــم وعندمــا حــاول‬\n‫إبعــاده عــن والدتــه وأخواتــه ضربــه املدعــى عليــه ممــا تســبب يف إصابتــه‬\n‫كمــا أفــاد أن املدعــى عليــه يقــوم بشــرب املســكر خــارج املنــزل وأنــه‬\n‫حضــر إلــى املنــزل وهــو بحالــة غيــر طبيعيــة وبإثبــات حالــة املدعــى عليــه‬\n‫مــن قبــل الفرقــة القابضــة اتضــح أنــه بحالــة غيــر طبيعيــة وتفــوح منــه‬\n‫رائحــة كريهــة تشــبه رائحــة املســكر وأنــه كان هائجـ ًا ويســب كل‬\n‫مــن حولــه وغيــر متــزن يف كالمــه وحركاتــه وباســتجواب املدعــى‬\n‫عليــه أقــر بشــربه للمســكر وبضربــه أخيــه وقــد صــدر بحــق املجنــي‬\n‫عليــه ‪..... /‬التقريــر الطبــي مــن مستشــفى األنصــار باملدينــة املنــورة برقــم‬\n‫(‪ ).....‬وتاريخ‪1434/4/10‬ه ـ متضمنـ ًا إصابتــه بخدش بالســاعد األيســر‬\n‫ومــدة الشــفاء أربعــة أيــام وقــد انتهــى التحقيــق إلــى اتهــام ‪..... /‬بشــرب‬\n‫املســكر وعقــوق والدتــه بالتهجــم عليهــا ومحاولــة ضربهــا وتهديــده‬\n‫ألخواتــه وضــرب أخــاه ممــا تســبب يف إصابتــه املوصوفــة بالتقريــر‬\n‫الطبــي وذلــك لألدلــة والقرائــن التاليــة ‪1 :‬ـ مــا ورد يف اعترافــه املنــوه‬\n‫عنــه املــدون يف مبلــف التحقيــق املرفــق لفــه (‪2 )1‬ـ مــا ورد يف أقــوال‬\n‫والدتــه وأخيــه املشــار إليهمــا املدونــان مبلــف االجــراءات املرفــق لفــه (‪)1‬‬\n\n\n                                                                                       ‫‪204‬‬\n\f      ‫‪3‬ـ محضــر إثبــات احلالــة املشــار إليــه املــدون مبلــف االجــراءات املرفــق لفه‬\n      ‫(‪4 )1‬ـ التقريــر الطبــي املنــوه عنــه املرفــق لفــه (‪ )4‬وحيــث إن مــا أقــدم‬\n      ‫عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا‬\n      ‫أســند إليــه واحلكــم عليــه بحــد املســكر لقــاء شــربه املســكر وتعزيــره‬\n      ‫مبــا يزجــره ويــردع غيــره لقــاء عقوقــه لوالدتــه ومحاولــة ضربهــا وضربــه‬\n      ‫ألخيــه ملــا حــال دونهــا وتهديــده إلخوانــه وتشــديد العقوبــة عليــه لعظــم‬\n      ‫جرمــه وألنــه أضحــى خطــر ًا علــى مــن هــي أولــى النــاس بصحبتــه وعلــى‬\n      ‫جميــع أســرته علمـ ًا بــأن احلــق اخلــاص لــم ينتــه بعــد وهــو ســجني علــى ذمــة‬\n      ‫هــذه الدعــوى منــذ تاريــخ ‪ 1434/4/9‬ه ـ هــذه دعــواي وبســؤال املدعــى‬\n      ‫عليــه عمــا جــاء بدعــوى املدعــي العــام أجــاب قائــا مــا ذكــره املدعــي‬\n      ‫العــام يف دعــواه صحيــح جملــة وتفصيــا ففــي التاريــخ املذكــور يف‬\n      ‫الدعــوى شــربت العــرق املســكر باملدينــة املنــورة وقــد دخلــت إلــي املنــزل‬\n      ‫الــذي تســكنه والدتــي املذكــورة يف الدعــوى و إخوانــي ذكورنــا‬\n      ‫و إناثنــا وقــد غضبــت علــى والدتــي و إخوانــي علــى تســكينهم زوج‬\n      ‫أختــي يف املنــزل فرفعــت صوتــي علــى أمــي و كلمتهــا بعنــف وتلفظــت‬\n      ‫عليهــا ســبا ألجــل ذلــك ولــم أمتثــل أمرهــا وقــد قــام شــقيقي ‪.....‬مبنعــي‬\n      ‫مــن الوصــول إلــى أمــي فتشــابكت معــه باأليــدي وقــد حضــر رجــال‬\n      ‫األمــن وقبضــوا علــى داخــل املنــزل هكــذا أجــاب هــذا وقــد حضــرت يف‬\n      ‫اجللســة ‪..........‬ســعودية اجلنســية بالســجل املدنــي رقــم ‪.....‬واملعــرف عليهــا‬\n      ‫مــن قبــل ‪.....‬ســعودي بالســجل املدنــي رقــم ‪.....‬ومــن قبــل املدعــى عليــه‬\n      ‫و أدعــت قائلــة إن املدعــى عليــه هــذا احلاضــر ابنــي يعصانــي ويعقنــي‬\n      ‫ويحــاول االعتــداء علــي أكثــر مــن مــرة ويتكاســل يف الطاعــات‬\n      ‫ويشــرب املســكرات ويف التاريــخ املذكــور يف الدعــوى حــاول االعتــداء‬\n\n\n‫‪205‬‬\n\f‫علــي فحــال بينــي وبينــه ابنــي ‪.....‬املعــرف بــي وقــد اعتــدى علــى إخوانــه و‬\n‫أخواتــه و أخشــى منــه علــي وعلــى إخوانــه و أطلــب تأديبــه علــى عقوقــه‬\n‫وســبه وشــتمه ومحاولــة اعتدائــه علــي وعلــى إخوانــه وضــم دعــواي هــذه‬\n‫مــع الدعــوى العامــة وبســؤال املدعــى عليــه عمــا جــاء بدعــوى املدعيــة‬\n‫أجــاب قائــا إن املدعيــة والدتــي و هــي صادقــة يف جميــع دعــواه و أنــا‬\n‫نــادم علــى عقوقــي لهــا هكــذا أجــاب كمــا قرر‪..........‬املنــوه عنــه آنفــا‬\n‫تنازلــه عــن شــقيقه املدعــى عليــه فيمــا حلقــه مــن إصابــات مــن أخيــه بغيــر‬\n‫مقابــل فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى‬\n‫عليــه صــادق علــى دعــوى املدعــي العــام فأقــر بشــرب العــرق املســكر‬\n‫وعقوقــه لوالدتــه وســبها وشــتمها محــاوال االعتــداء عليهــا وعلــى إخوانــه‬\n‫ومبــا أن العلمــاء قــد أجمعــوا علــى أن مــن شــرب املســكر حالــة كونــه‬\n‫طائعــا مختــارا فيقــام عليــه حــد املســكر لعمــوم قــول النبــي صلــي اهلل‬\n‫عليــه وســلم ( كل مســكر خمــر وكل خمــر حــرام ) ومبــا أن الشــرع‬\n‫أمــر باإلحســان إلــى الوالديــن فقــال ســبحانه ( وقضــى ربــك أن ال تعبــدوا‬\n‫إال إيــاه وبالوالديــن إحســانا ) اآليــة ومبــا أن عقــوق الوالديــن كبيــرة‬\n‫مــن أكبــر الكبائــر ملــا ثبــت يف الصحيــح أن النبــي صلــى اهلل عليــه‬\n‫وســلم قــال ( اال أخبركــم بأكبــر الكبائــر قالــو بلــى يــا رســول اهلل‬\n‫قــال اإلشــراك بــاهلل وعقــوق الوالديــن وكان متــكأ فجلــس ثــم قــال أال‬\n‫وقــول الــزور ) احلديــث ومبــا أن هــذه اجلنايــة وقعــت يف بلــد اهلل احلــرام‬\n‫الــذي رفــع اهلل مكانــه وتوعــد بالعقــاب علــى مــن انتهــك محارمــه ومبــا‬\n‫أن التعزيــر يشــرع يف كل معصيــة ال حــد فيهــا وال كفــارة وهــو يختلــف‬\n‫باختــاف األحــوال واألشــخاص والزمــان واملــكان وتقديــر ذلــك راجــع‬\n‫إلــي نظــر احلاكــم ومبــا يــراه محققــا للزجــر والــردع جلميــع مــا ذكــر‬\n\n\n                                                                                       ‫‪206‬‬\n\f      ‫فقــد حكمــت مبــا يلــي أوال يجلــد املدعــى عليهمــا ثمانــن جلــدة حــد‬\n      ‫املســكر تقــع علــى بدنــه دفعــة واحــدة أمــام جمــع مــن النــاس ثانيــا يعــزر‬\n      ‫املدعــى عليــه للحقــن العــام واخلــاص مناصفــة وذلــك بجلــده ســتمائة‬\n      ‫جلــدة تقــع علــى بدنــه علــى اثنتــي عشــرة دفعــة وبــن كل دفعــة و أخــرى‬\n      ‫عشــرة أيــام وبــن احلــد والتعزيــر مثــل ذلــك ويســجن ســنة كاملــة ابتــداء‬\n      ‫مــن تاريــخ إيقافــه ويؤخــذ عليــه التعهــد بعــدم العــودة ملثــل ذلــك ثالثــا ثبــت‬\n      ‫لــدي تنــازل ‪.....‬عــن دعــواه هــذه ضــد أخيــه املدعــى عليــه وبعرضــه قــرر‬\n      ‫املدعــي العــام واملدعــى عليــه عــدم قناعتهمــا باحلكــم وطلبــا رفعــه إلــي‬\n      ‫محكمــة االســتئناف بــدون الئحــة اعتراضيــة فأجيــب لطلبهمــا أمــا‬\n      ‫املدعيــة فقــررت قناعتهــا باحلكــم وقــد انتهــت اجللســة يف متــام الســاعة‬\n      ‫‪ 12 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/08‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعد ‪ -:‬فقد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 341121165‬وتاريــخ‬\n      ‫‪1434/5/19‬ه ـ املرفــق بهــا القــرار الشــرعي رقــم ‪ 34210183‬وتاريــخ‬\n      ‫‪1434/5/8‬ه ـ الصــادر مــن فضيلــة الشــيخ‪.......... /‬القاضــي باحملكمــة‬\n      ‫اجلزائيــة باملدينــة املنــورة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪..... /‬‬\n      ‫املتهــم بشــرب املســكر وعقــوق والدتــه والتهجــم عليهــا ومحاولــة ضربها‬\n      ‫احملكــوم فيــه مبــا دون باطنــه بدراســة احلكــم وصــورة ضبطــه قررنــا‬\n      ‫باألكثريــة املوافقــة علــى احلكــم واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                     ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪207‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":202,"source_page_end":207,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f7eff41bb81a89ced13f12c0dd3022bb3c2ee22b47907e8de20550b1c5bf4154","normalized_text_hash":"ebc3c9be3705a049c47eab0f65da8da63139cf52a3e3fbc6511f3ef0f959ed6b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p202-34210183"},{"id":"d1c52bc0-1bbd-5466-a4e8-6553c5c03021","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -فعل الفاحشة ببهيمة -املدعى عليهما غير مسلمني -ال يقام حد املسكر على غير مسلم -التعزير باجللد والسجن باإلضافة للتوصية باإلبعاد -تغليظ العقوبة لبشاعة","document_number":"34211876","case_number":"34214997","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالسعيرة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/12","year":"1434","subject":"مسكر -شرب مسكر -فعل الفاحشة ببهيمة -املدعى عليهما غير مسلمني -ال يقام حد املسكر على غير مسلم -التعزير باجللد والسجن باإلضافة للتوصية باإلبعاد -تغليظ العقوبة لبشاعة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34211876:‬تاريخه‪1434/5/12 :‬هـ‬\n                   ‫رقم الدعوى‪34214997:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34240877:‬تاريخه‪1434/06/14:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب مســكر‪ -‬فعــل الفاحشــة ببهيمــة ‪ -‬املدعــى عليهمــا غيــر‬\n‫مســلمني ‪ -‬ال يقــام حــد املســكر علــى غيــر مســلم ‪ -‬التعزيــر باجللــد‬\n‫والســجن باإلضافــة للتوصيــة باإلبعــاد ‪ -‬تغليــظ العقوبــة لبشــاعة‬\n                                                                   ‫اجلــرم ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه تعالــى ( والذيــن هــم لفروجهــم حافظــون إال علــى أزواجهــم‬\n‫أو مــا ملكــت أميانهــم فإنهــم غيــر ملومــن فمــن ابتغــى وراء ذلــك‬\n                                                  ‫فأولئــك هــم العــادون )‪.‬‬\n‫‪ -2‬قــال شــيخ اإلســام رحمــه اهلل ( وأمــا مــا يســتخفون بــه يف بيوتهــم‬\n    ‫مــن غيــر ضــرر باملســلمني بوجــه مــن الوجــوه فــا يتعــرض لهــم ) ‪.‬‬\n        ‫‪ -3‬قال البهوتي رحمه اهلل (وال يحد ذمي وال مستأمن بشربه)‪.‬‬\n                    ‫‪ -4‬جاء يف الروض املربع ( ويعزر من أتى بهيمة ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا وهمــا أجنبيــان غيــر مســلمني‬\n‫بشــرب املســكر وفعــل الفاحشــة ببهيمــة ‪،‬وطلــب إثبــات مــا أســند‬\n‫إليهمــا وتعزيرهمــا لقــاء شــرب املســكر وفعــل الفاحشــة بالبهيمــة‬\n‫‪،‬حيــث قــام املدعــى عليهمــا بتنــاول املســكر ومــن ثــم فعــل الفاحشــة‬\n\n                                                                                 ‫‪208‬‬\n\f      ‫ببهيمــة ‪،‬وصــادق املدعــى عليهمــا بواســطة املترجــم علــى الدعــوى ‪،‬‬\n      ‫وأثبــت التقريــر الطبــي تعــرض البهيمــة لفعــل الفاحشــة ‪ ،‬وبنــاء علــى مــا‬\n      ‫تقــدم حكمــت احملكمــة بتعزيرهمــا بجلــد كل واحــد منهمــا ســبعني‬\n      ‫جلــدة دفعــة واحــدة لقــاء شــربهما املســكر وجلــد كل واحــد منهمــا‬\n      ‫خمســمائة جلــدة مفرقــة علــى دفعــات كل دفعــه قدرهــا خمســون جلــدة‬\n      ‫وســجنهما أربعــة أشــهر وإبعادهمــا عــن البــاد ‪،‬وقنــع املدعــى عليهمــا‬\n      ‫وصــدق احلكــم مــن‬    ‫باحلكــم واعتــرض املدعــي العــام بــدون الئحــة ‪ُ ،‬‬\n                                                            ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬رئيــس احملكمــة العامــة بالســعيرة‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالســعيرة برقــم ‪ 34214997‬وتاريــخ ‪1434/05/08‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341145552‬وتاريــخ ‪ 1434/05/08‬ه ـ ففــي يــوم‬\n      ‫األحــد املوافق‪1434/05/12‬ه ـ افتتحــت اجللســة يف متــام الســاعة ‪00‬‬\n      ‫‪ 11 :‬وفيهــا حضــر العريــف بالشــرطة مركز‪.....‬الســعودي بالســجل‬\n      ‫املدنــي رقم‪.....‬ســجل ‪.....‬بصفتــه مدعيــا عامـ ًا مبوجــب خطــاب التعميــد‬\n      ‫الــوارد مــن مديــر مركــز الشــرطة برقــم ‪.....‬يف ‪1434/5/12‬ه ـ واملقيــد‬\n      ‫لــدى احملكمــة برقــم ‪ 341165403‬يف ‪1434/5/12‬ه ـ وادعــى علــى‬\n      ‫احلاضريــن معــه ‪.....‬هنــدي اجلنســية مبوجــب اإلقامــة رقــم ‪.....‬ســارية‬\n      ‫املفعــول و‪.....‬هنــدي اجلنســية مبوجــب اإلقامــة رقــم ‪.....‬كمــا حضــر‬\n      ‫املترجــم ‪.....‬بنغالــي اجلنســية مبوجــب اإلقامــة ســارية املفعــول رقــم ‪.....‬‬\n      ‫ا يف حتريــر دعــواه بصفتــي مدعيــا عامــا‬   ‫ثــم ادعــى املدعــي العــام قائ ـ ً‬\n\n‫‪209‬‬\n\f‫ادعــي علــي احلاضريــن معــي يف اجللســة كل مــن ‪.....‬هنــدي اجلنســية‬\n‫باإلقامــة رقــم ‪.....‬و‪.....‬هنــدي اجلنســية باإلقامــة رقــم ‪.....‬حيــث إنــه‬\n‫بتاريــخ ‪ 1434/4/26‬قــام املذكــوران بتنــاول مــادة مســكره ومــن ثــم‬\n‫قامــوا بفعــل الفاحشــة ببهيمــة فقــد خلــص بإدانتهمــا مبــا نســب إليهمــا‬\n‫مــن تنــاول املســكر وفعــل الفاحشــة بالبهيمــة وذلــك لألدلــة والقرائــن‬\n‫التاليــة ‪ -1‬بــاغ املواطــن ‪ -2.....‬مــا ورد يف محضــر االنتقــال واملعاينــة‬\n‫املثبتــة مــن خــال مشــاهدة النعجــة رابضــة علــى األرض وبهــا كســر‬\n‫بالقــدم ووجــود آثــار أقــدام لشــخصني يقومــان بســحبها ‪ -3‬مــا ورد يف‬\n‫احملضــر املعــد مــن قبــل الطبيــب البيطــري املثبــت مــن خــال تعــرض‬\n‫النعجــة لفعــل الفاحشــة ووجــود آثــار عنــف علــى فرجهــا ‪ -4‬مطابقــة اثــر‬\n‫اقــدام املذكوريــن مــع االثــار املوجــودة باملوقــع ‪ -5‬مــا ورد يف اقــوال‬\n‫املذكوريــن عــن قيامهــم بتنــاول املســكر وفعــل الفاحشــة بالنعجــة ‪-6‬‬\n‫اعتــراف املذكوريــن مبــا ورد يف البنــد رقــم (‪ )5‬املصدقــة شــرع ًا لــذا‬\n‫اطلــب احلكــم علــى املذكوريــن باحلــق العــام هــذه دعــواي وبعــرض ذلــك‬\n‫علــى املدعــى عليهمــا عــن طريــق املترجــم أجــاب املدعــى عليــه األول ‪.....‬‬\n‫ا مــا ذكــره املدعــي العــام يف الدعــوى مــن شــربي ملــادة املســكر‬        ‫قائ ـ ً‬\n‫وقيامــي بفعــل الفاحشــة يف بهيمــة صحيــح هكــذا أجــاب كمــا أجــاب‬\n‫ا مــا ذكــره املدعــي العــام يف الدعــوى مــن‬  ‫املدعــى عليــه الثانــي ‪.....‬قائـ ً‬\n‫شــربي ملــادة املســكر وقيامــي بفعــل الفاحشــة يف بهيمــة صحيــح هكذا‬\n‫أجــاب ثــم جــرى ســؤال املدعــى عليهمــا هــل همــا مســلمان فأجــاب كل‬\n‫ا إنــه غيــر مســلم ثــم جــرى ســؤال املدعــى‬    ‫واحــد منهمــا منفــرد ًا قائ ـ ً‬\n‫ا لقــد‬  ‫عليهمــا أيــن مت شــرب املســكر فأجــاب املدعــى عليــه األول قائـ ً‬\n‫شــربنا املســكر يف داخــل غرفتنــا هكــذا أجــاب كمــا أجــاب املدعــى‬\n\n\n                                                                                         ‫‪210‬‬\n\f      ‫ا لقــد شــربنا املســكر داخــل غرفتنــا هكــذا أجــاب‬            ‫عليــه الثانــي قائ ـ ً‬\n      ‫ثــم جــرى ســؤال املدعــى عليهمــا هــل همــا متزوجــان فأجــاب املدعــى‬\n      ‫ا نعــم إننــي متــزوج هكــذا أجــاب كمــا أجــاب املدعــى‬          ‫عليــه األول قائـ ً‬\n      ‫ا نعــم إننــي متــزوج هكــذا أجــاب ثــم جــرى تفحــص‬           ‫عليــه الثانــي قائ ـ ً‬\n      ‫أوراق املعاملــة ومــن ضمــن لفاتهــا اللفــة رقــم (‪ )15‬املتضمنــة عــدم وجــود‬\n      ‫ســوابق علــى املدعــى عليهمــا كمــا جــرى االطــاع علــى ملــف تقريــر‬\n      ‫األحــوال األمنيــة صحيفــة رقــم (‪15‬و‪ )16‬فوجــد اعترافهمــا املصــدق‬\n      ‫شــرع ًا علــى مــا جــاء يف الدعــوى فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة لكــون املدعــي العــام يطالــب بتعزيــر املدعــى عليهمــا لقــاء‬\n      ‫قيامهمــا بشــرب املســكر وفعــل الفاحشــة ببهيمــة و لكــون املدعــى‬\n      ‫عليهمــا أقــرا بشــرب املســكر وفعــل الفاحشــة بالبهيمــة وال عــذر ملــن‬\n      ‫أقــر ولكــون املدعــى عليهمــا غيــر مســلمني فــا يقــام عليهمــا حــد شــرب‬\n      ‫املســكر خاصــة وأنهمــا لــم يشــهرا شــربهما ألنهمــا يعتقــدان حلــه قــال‬\n      ‫شــيخ اإلســام ابــن تيمــة رحمــه اهلل تعالــى «وأمــا مــن يســتخفون بــه يف‬\n      ‫بيوتهــم مــن غيــر ضــرر باملســلمني بوجــه مــن الوجــوه فــا يتعــرض لهــم «‬\n      ‫وقــال البهوتــي رحمــه اهلل تعالــى «وال يحــد ذمــي وال مســتأمن بشــربه «‬\n      ‫يقصــد املســكر إال أنــه يعــزر لقــاء مخالفتــه لألنظمــة والتعليمــات التــي‬\n      ‫التــزم بتطبيقهــا عنــد إقامتــه يف هــذه البــاد احترام ـ ًا لســيادة الدولــة‬\n      ‫كمــا أنــه ال يقــام عليهمــا حــد الزنــا لكونهمــا غيــر مســلمني ولعــدم‬\n      ‫توافــر شــروط الزنــا والتــي منهــا تغييــب حشــفة أصليــة يف قبــل أو دبــر‬\n      ‫آدمــي حــي فقــد ســقط ضابــط وهــو قبــل أو دبــر آدمــي إذ إنهمــا فعــا‬\n      ‫الفاحشــة يف بهيمــة وال يعنــي ذلــك عــدم شــناعة مــا قامــا بــه وإمنــا الواجــب‬\n      ‫فيهمــا التعزيــر لكونهمــا ارتكبــا فاحشــة شــنيعة بشــعة متجهــا الفطــر‬\n\n\n‫‪211‬‬\n\f‫ا عــن الشــريعة اإلســامية وقــد جــاء يف الــروض املربــع‬      ‫الســليمة فض ـ ً‬\n‫مــا نصــه «ويعــزر مــن أتــى بهيمــة» ولقولــه تعالــى «والذيــن هــم لفروجهــم‬\n‫حافظــون إال علــى أزواجهــم أو مــا ملكــت إميانهــم فإنهــم غيــر ملومــن‬\n‫فمــن ابتغــى وراء ذلــك فأولئــك هــم العــادون» فقــد أبــاح ســبحانه للرجــل‬\n‫أزواجــه و إمــاءه وجعــل مــا وراء ذلــك اعتــداء محرم ـ ًا ويتأكــد التعزيــر‬\n‫يف حــق املدعــى عليهمــا لكونهمــا متزوجــن ولكــون املدعــى عليهمــا‬\n‫أجانــب وإبقاؤهــم يف الســجن مــدة طويلــة ال داعــي لهــا ممــا يســتدعي‬\n‫أن يــزاد يف اجللــد وتقلــل مــدة الســجن ولعــدم وجــود ســوابق لديهمــا فلــذا‬\n‫وجلميــع مــا تقــدم فقــد قــررت اآلتــي أو ًال ثبــت لــدي شــرب املدعــى عليهمــا‬\n‫‪.....‬هنــدي مبوجــب إقامــة رقــم ‪.....‬و ‪.....‬هنــدي مبوجــب إقامــة رقــم ‪.....‬‬\n‫للمســكر وقيامهــا بفعــل الفاحشــة يف بهيمــة ثانيـ ًا قــررت تعزيــر املدعــى‬\n‫عليهمــا املذكوريــن بجلــد كل واحــد أربعــن جلــدة لقــاء شــربهما‬\n‫املســكر ثالث ـ ًا قــررت تعزيــر املدعــى عليهمــا املذكوريــن بجلــد كل‬\n‫واحــد منهمــا خمســمائة جلــدة مفرقــة علــى عشــر دفعــات متســاوية كل‬\n‫دفعــة قدرهــا خمســون جلــدة وســجنهما ملــدة أربعــن يومــا حتتســب منهــا‬\n‫مــدة إيقافهمــا علــى ذمــة هــذه القضيــة وبذلــك حكمت وبعــرض احلكم‬\n‫علــى املدعــي العــام قــرر عــدم قناعتــه باحلكــم وطلــب رفــع املعاملــة‬\n‫حملكمــة االســتئناف بــدون الئحــة كمــا جــرى عــرض احلكــم علــى‬\n‫املدعــى عليهمــا عــن طريــق املترجــم فقــررا قناعتهمــا بــه وســوف يتــم رفــع‬\n‫املعاملــة حملكمــة االســتئناف بعــد إكمــال الزمهــا واختتمــت اجللســة يف‬\n‫متــام الســاعة الثانيــة عشــر وللبيــان حــرر يف ‪1434/4/12‬ه ـ وأســتغفر‬\n         ‫اهلل وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه أجمعــن‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء املوافــق ‪1434/7/11‬ه ـ‬\n\n\n                                                                                       ‫‪212‬‬\n\f      ‫افتتحــت اجللســة يف متــام الســاعة احلاديــة عشــر والنصــف وفيهــا‬\n      ‫حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليهمــا كمــا حضــر‬\n      ‫املترجــم ‪.....‬املذكــور وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫باملنطقــة الشــرقية بخطــاب فضيلــة رئيســها رقــم ‪ 341214943‬يف‬\n      ‫‪1434/6/29‬ه ـ واملتضمــن صــدور القــرار املســجل برقــم ‪/ 34240877‬‬\n      ‫ج‪/1‬ب يف ‪1434/6/14‬ه ـ وباالطــاع عليــه تبــن أنــه صــادر مــن الدائــرة‬\n      ‫اجلزائيــة الثالثيــة األولــى ويتضمــن نــص احلاجــة منــه «وبدارســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة لوحــظ أوالً‪ :‬أن مــا حكــم بــه فضيلتــه‬\n      ‫علــى املدعــى عليهمــا مــن شــرب املســكر قليــل ثاني ـ ًا مــا حكــم بــه‬\n      ‫فضيلتــه علــى املدعــى عليهمــا جــراء مــا اقترفــاه بالبهيمــة مــن ســجن‬\n      ‫قليــل ثالث ـ ُا لــم جنــد أن فضيلتــه أجــرى شــيئ ًا حيــال البهيمــة رابع ـ ًا أال‬\n      ‫يــرى فضيلتــه التوجيــه بإبعــاد املدعــى عليهمــا حفظـ ًا للمجتمــع ملالحظــة‬\n      ‫مــا ذكــر وإكمــال الــازم ومــن ثــم إعــادة املعاملــة واهلل املوفــق وصلــى‬\n      ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/6/13‬ه ـ‬\n      ‫قاضــي اســتئناف ‪.....‬ختمــه وتوقيعــه قاضــي اســتئناف ‪..........‬ختمــه‬\n      ‫وتوقيعــه رئيــس الدائــرة ‪.....‬ختمــه وتوقيعــه وجواب ـ ًا علــى مالحظــات‬\n      ‫أصحــاب الفضيلــة أقــول بالنســبة ملــا ذكــره أصحــاب الفضيلــة حفظهــم‬\n      ‫اهلل تعالــى يف املالحظــة األولــى والثانيــة والرابعــة فهــو وجيــه وبالنســبة‬\n      ‫للمالحظــة الثالثــة فقــد مت الرجــوع إلــى أوراق القضيــة ومــن بــن لفاتهــا‬\n      ‫اللفــة رقــم (‪ )15‬املتضمنــة التقريــر النهائــي للقضيــة ومــن ضمنهــا‬\n      ‫التصــرف بالبهيمــة ومفــاده قيــام املواطــن ‪..........‬صاحــب البهيمــة بذبــح‬\n      ‫النعجــة وإتالفهــا أ‪.‬ه ـ وبذلــك ال يوجــد مــا يتــم إجــراؤه حيــال البهيمــة‬\n      ‫لزوالهــا فلــذا وجلميــع مــا ذكــر فقــد قــررت اآلتــي أو ًال رجعــت عمــا‬\n\n\n‫‪213‬‬\n\f‫حكمــت بــه يف الفقــرة ثاني ـ ًا وثالث ـ ًا مــن جلــد وســجن للمدعــى عليهمــا‬\n‫وقــررت تعزيــر املدعــى عليهمــا بجلــد كل واحــد منهمــا ســبعني جلــدة‬\n‫دفعــة واحــدة لقــاء شــربهما للمســكر وتعزيرهمــا بجلــد كل واحــد‬\n‫منهمــا خمســمائة جلــدة مفرقــة علــى عشــر دفعــات متســاوية كل دفعــة‬\n‫قدرهــا خمســون جلــدة وســجنهما ملــدة أربعــة أشــهر حتتســب منهــا‬\n‫مــدة إيقافهمــا علــى ذمــة هــذه القضيــة لقــاء قيامهمــا بفعــل الفاحشــة‬\n‫بالبهيمــة وبذلــك حكمــت كمــا أوصــي بإبعــاد املدعــى عليهمــا عــن‬\n‫اململكــة حفاظ ـ ًا علــى املجتمــع وبعــرض ذلــك علــى املدعــي العــام قــرر‬\n‫عــدم قناعتــه باحلكــم وطلــب رفعــه بــدون الئحــة اعتراضيــة كمــا قــرر‬\n‫املدعــى عليهمــا قناعتهمــا بــه وعليــه ســوف يتــم إعــادة املعاملــة حملكمــة‬\n‫االســتئناف إلكمــال الزمهــا واختتمــت اجللســة يف متــام الســاعة الثانيــة‬\n‫عشــر وللبيــان حــرر يف ‪1434/7/11‬ه ـ وأســتغفر اهلل وصلــى اهلل وســلم‬\n                                    ‫علــى نبينــا محمــد وآلــه صحبــه أجمعــن ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بالســعيرة الشــيخ ‪.....‬برقــم‬\n‫‪ 341214943‬وتاريــخ ‪1434/7/11‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n‫‪ 34/1778109‬وتاريــخ ‪1434/7/23‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلتــه املســجل برقــم ‪ 34211876‬وتاريــخ ‪1434/5/12‬ه ـ اخلــاص‬\n‫بدعوى‪/‬املدعــي العــام ضــد‪ .......... -1/‬هنــدي اجلنســية ‪..... -2‬هنــدي‬\n‫اجلنســية يف قضيــة مســكر وفاحشــه يف بهيمــه وقــد تضمــن القــرار‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬حيــث ســبق دراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n\n\n                                                                                         ‫‪214‬‬\n\f      ‫فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا‬\n      ‫رقــم‪ 34240877‬يف‪1434/6/14‬ه ـ املصادقــة علــى احلكــم بعد اإلجراء‬\n      ‫األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                ‫وســلم حــرر يف ‪1434/8/3‬ه ـ ‪.‬‬\n\n\n\n\n‫‪215‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":208,"source_page_end":215,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"96935b8a63676cc00770b70485b6e33f95e8073657a0151b26e843876b1ff843","normalized_text_hash":"6ddde1f0434a1bc9453b9e736841cd449c2c5211e269bb732829542750a9674e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p208-34211876"},{"id":"72ffc2e5-5271-5db4-8551-4e896d3476c9","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حد املسكر -مقاومة رجال األمن -احلكم بالقرائن -التعزير بالسجن واجللد .","document_number":"34370781","case_number":"34229617","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/26","year":"1434","subject":"مسكر -شرب املسكر -حد املسكر -مقاومة رجال األمن -احلكم بالقرائن -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34370781:‬تاريخه‪1434/11/26:‬هـ‬\n                    ‫رقم الدعوى‪34229617:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 35122870:‬تاريخه‪1434/01/22:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر‪ -‬حــد املســكر ‪ -‬مقاومــة رجــال األمــن ‪ -‬احلكــم‬\n                               ‫بالقرائــن ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( مــن شــرب اخلمــر فاجلــدوه ) رواه‬\n                                          ‫أحمــد وأبــو داود والنســائي ‪.‬‬\n‫‪ -2‬إجمــاع الصحابــة علــى جلــد شــارب اخلمــر ثمانــن جلــدة وهــو‬\n    ‫املذهــب وعليــه جماهيــر األصحــاب ( كشــاف القنــاع ‪) 99/14‬‬\n                                                 ‫و( االنصاف ‪. )441/15‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر ومقاومــة رجــال‬\n‫األمــن والتهجــم عليهــم ‪،‬وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n‫بحــد املســكر وتعزيــره لقــاء مقاومــة رجــال األمــن وتشــديد العقوبــة‬\n‫وفــق األنظمــة والتعليمــات ‪،‬حيــث ورد بــاغ مــن أحــد األشــخاص بقيــام‬\n‫املدعــى عليــه بالتهجــم عليــه يف داخــل بيتــه واالعتــداء عليــه بالضــرب‬\n‫وتهديــده بالقتــل وتنبعــث رائحــة املســكر منــه وأثنــاء القبــض عليــه قــام‬\n‫مبقاومــة رجــال األمــن والتهجــم عليهــم ‪،‬وباستشــمامه تبــن انبعــاث‬\n‫رائحــة املســكر منــه وتعــذر اســتجوابه كونــه بحالــة ســكر ‪،‬وصــادق‬\n\n                                                                                   ‫‪216‬‬\n\f      ‫املدعــى عليــه علــى شــرب املســكر وأنكــر مقاومــة رجــال األمــن ‪،‬وبنــاء‬\n      ‫علــى مــا تقــدم حكمــت احملكمــة بجلــده ثمانــن جلــدة دفعــة واحــدة‬\n      ‫يف مــكان عــام حــد املســكر وســجنه أســبوع ًا وجلــده خمســن جلــدة‬\n      ‫تعزيــر ًا لقــاء تهمــة مقاومــة رجــال األمــن والتهجــم عليهــم ‪،‬وقنــع املدعــى‬\n      ‫‪،‬وصــدق‬‫ُ‬     ‫عليــه واعتــرض املدعــي العــام مكتفي ـ ًا بالئحــة الدعــوى‬\n                                              ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا ‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n      ‫مــن هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 341215464‬وتاريــخ ‪1434/5/19‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 34229617‬وتاريــخ ‪1434/5/19‬ه ـ‬\n      ‫افتتحــت اجللســة يف يــوم األربعــاء ‪1434/11/26‬ه ـ الســاعة الثامنــة‬\n      ‫والثلــث وفيهــا قــدم املدعــي العــام ‪.....‬دعــواه ونصهــا اآلتــي‪ :‬بصفتــي‬\n      ‫مدعيـ ًا عامـ ًا بدائــرة االدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪/‬‬\n      ‫‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬حيــث إنــه بتاريــخ‬\n      ‫‪1434/4/13‬ه ـ وأثنــاء قيــام إحــدى الدوريــات األمنيــة بعملهــا املعتــاد‬\n      ‫وردهــم بــاغ عــن وجــود شــخص يفيــد بقيــام املدعــى عليــه بالتهجــم عليــه‬\n      ‫يف داخــل بيتــه واالعتــداء عليــه بالضــرب وتهديــده بالقتــل وتنبعــث منــه‬\n      ‫رائحــة املســكر وأثنــاء القبــض عليــه قــام بالتهجــم علــى رجــال األمــن‬\n      ‫ومقاومتهــم ومت إحالتــه ملركــز شــرطة شــمال الدمــام وباستشــمام‬\n      ‫املدعــى عليــه اتضــح انبعــاث رائحــة املســكر منــه كمــا تعذر اســتجوابه‬\n\n‫‪217‬‬\n\f‫كونــه بحالــة ســكر وبضبــط أقــوال املبلــغ ‪.....‬أفــاد بقيــام املدعــى عليــه‬\n‫بالدخــول ملمــر عمارتــه التــي يقطــن بهــا جميــع ســاكني العمــارة ومفتــوح‬\n‫لهــم ولــم يقــم بالدخــول إلــى داخــل شــقته واالعتــداء عليــه بضربــه ولــم‬\n‫يحــدث لــه أي إصابــات جــراء قيامه بضربه وتهديده بالقتل كونه كان‬\n‫بحالــة ســكر كمــا جــرى ضبــط أقــوال املواطــن ‪.....‬حيــث أفــاد بتعرض‬\n‫املدعــى عليــه لزوجتــه وشــقيقها ‪..........‬بالتلفــظ عليهمــا بألفــاظ بذيئــة‬\n‫(مت حفــظ دعــوى املدعيــان باحلــق اخلــاص بأمــر احلفــظ رقــم ‪.....‬وتاريــخ‬\n‫‪1434/4/28‬ه ـ اســتناد ًا للمــادة ‪ 124‬مــن نظــام اإلجــراءات اجلزائيــة)‬\n‫وبســماع أقــوال املدعــى عليــه أقــر بشــربه للمســكر وباســتجوابه أقــر‬\n‫بشــربه للمســكر وعــدم تذكــره ملــا حــدث بينــه وبــن املدعــي كونــه‬\n‫بحالــة ســكر وانتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه‬\n‫بشــربه للمســكر ومقاومتــه لرجــال األمــن والتهجــم عليهــم وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪-1 :‬مــا جــاء بإقــراره املــدون علــى الصفحــة رقــم‬\n‫(‪ )11‬مــن ملــف االســتدالل املرفــق لفــه رقــم (‪-2 )1‬مــا جــاء بإقــراره مــن‬\n‫خــال اســتجوابه املرفــق لفــه رقــم ( ‪-3 ) 7 ، 6 ، 5‬مــا جــاء مبحضــر‬\n‫اإلستشــمام وتعــذر االســتجواب املــدون علــى الصفحــة رقــم (‪ )11، 6‬مــن‬\n‫ملــف االســتدالل املرفــق لفــه رقــم (‪-4 )2‬مــا جــاء مبحضــر تنفيــذ املهمــة‬\n‫املرفــق لفــه رقــم (‪ )3‬وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه‬\n‫واحلكــم عليــه مبــا يلــي ‪-1:‬بحــد املســكر لقــاء شــربه لــه ‪ -2‬بعقوبــة‬\n‫تعزيريــه تزجــره وتــردع غيــره لقــاء قيامــه مبقاومــة رجــال األمــن وتشــديد‬\n‫العقوبــة عليــه وفق ـ ًا لتعميــم صاحــب الســمو امللكــي النائــب الثانــي‬\n\n\n                                                                                      ‫‪218‬‬\n\f      ‫لرئيــس مجلــس الــوزراء وزيــر الداخليــة حفظــه اهلل رقــم (‪)118012‬‬\n      ‫وتاريــخ ‪1431/10/26‬ه ـ (علمـ ًا بــأن احلــق اخلــاص انتهــى بالتنــازل فيمــا‬\n      ‫يتعلــق بدعــوى املدعيــان باحلــق اخلــاص) هكــذا ادعــى وبعــرض دعــوى‬\n      ‫ا مــا ذكــره املدعــي العــام‬‫املدعــي العــام علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫مــن شــربي للمســكر فذلــك صحيــح وأمــا مقاومــة رجــال األمــن فــا‬\n      ‫أتذكــر شــيئ ًا حيــث كنــت يف حالــة ســكر وال توجــد علــي ســوابق‬\n      ‫هكــذا أجــاب وبســؤال املدعــي العــام البينــة علــى دعــواه قــال أطلــب‬\n      ‫الرجــوع إلــى املعاملــة هكــذا أجــاب ثــم جــرى الرجــوع إلــى املعاملــة‬\n      ‫فوجــدت علــى لفــة رقــم (‪ )2‬دفتــر التحقيــق ص (‪ )6‬محضــر استشــمام‬\n      ‫املتضمــن انبعــاث رائحــة املســكر مــن أنفاس املدعــى عليه كما وجدت‬\n      ‫علــى لفــة رقــم (‪ )3‬محضــر تنفيــذ مهمــة املتضمــن طبــق مــا ذكــر املدعي‬\n      ‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي العــام وإجابــة‬ ‫العــام يف دعــواه فبنـ ً‬\n      ‫املدعــى عليــه وإقــراره بشــرب املســكر وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرع ًا ولقولــه صلــى اهلل عليــه وســلم (مــن شــرب اخلمــر فاجلــدوه) رواه‬\n      ‫أحمــد وأبــو داود والنســائي كمــا انعقــد إجمــاع الصحابــة رضــي اهلل‬\n      ‫عنهــم علــى جلــد شــارب اخلمــر ثمانــون جلــدة (كشــاف القنــاع عــن‬\n      ‫اإلقنــاع ‪)99/14‬وهــو املذهــب وعليــه جماهيــر األصحــاب (اإلنصــاف‬\n      ‫‪ )441/15‬ومبــا أن محضــر تنفيــذ املهمــة قرينــة تؤيــد دعــوى املدعــي‬\n      ‫العــام ونظــر ًا لعــدم اكتمــال البينــة علــى قيــام املدعــى عليــه بالتهجــم‬\n      ‫علــى رجــال األمــن ومقاومتهــم لــذا كلــه فقــد ثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه بشــرب املســكر وقــررت اآلتــي‪ :‬أوالً‪ :‬جلــده ثمانــن جلــدة دفعــة‬\n      ‫واحــدة حــد املســكر ويكــون التنفيــذ يف مــكان عــام يحضــره جمــع‬\n      ‫مــن النــاس‪ .‬ثانيـاً‪ :‬ســجنه ملــدة أســبوع حتتســب منهــا مــدة إيقافــه وجلــده‬\n\n\n‫‪219‬‬\n\f‫خمســن جلــدة تعزيــر ًا دفعــة واحــدة لقــاء تهمــة مقاومــة رجــال األمــن‬\n‫والتهجــم عليهــم‪ .‬وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن قــرر‬\n‫املدعــى عليــه القناعــة باحلكــم كمــا قــرر املدعــي العــام االعتــراض‬\n‫علــى احلكــم مكتفي ـ ًا بالئحــة الدعــوى العامــة وأمــرت برفــع املعاملــة‬\n‫إلــى محكمــة االســتئناف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                              ‫محمــد‪ .‬حــرر يف ‪1434/11/26‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم‪/34/2899140‬ج‪ 2‬وتاريــخ ‪1434/12/26‬ه ـ‬\n‫الــواردة مــن فضيلــة‪ /‬رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم‬\n‫‪ 342125464‬وتاريــخ ‪1434/12/23‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ..... /‬املســجل برقــم ‪34370781‬‬\n‫وتاريــخ ‪1434/11/26‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪..... /‬يف‬\n‫قضيــة مســكر ومقاومــة رجــال األمــن والتهجــم عليهــم وقــد تضمــن‬\n‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل‬\n‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                  ‫‪1435/01/22‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                         ‫‪220‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":216,"source_page_end":220,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9a7d74e3334d7e09d21390c09ff06026a7f86a05d75b0a230f44d63eee85d37c","normalized_text_hash":"26133a2db7664d1d68c795850fe32eee261db3cc26da144cd18e39751696417b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p216-34370781"},{"id":"df9d0b47-5bc9-56d7-8a50-cf2049d8c111","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازته احلشيش املخدر بقصد الترويج واالستعمال -تستر على هارب -حد املسكر -أسباب مخففة","document_number":"34294519","case_number":"34237103","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/10","year":"1434","subject":"مسكر -شرب املسكر -حيازته احلشيش املخدر بقصد الترويج واالستعمال -تستر على هارب -حد املسكر -أسباب مخففة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫رقم الصك‪ 34294519:‬تاريخه‪1434/8/10:‬هـ‬\n                         ‫رقم الدعوى‪34237103:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 35100015:‬تاريخه‪1434/01/01:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬حيازتــه احلشــيش املخــدر بقصــد الترويــج‬\n      ‫واالســتعمال ‪ -‬تســتر علــى هــارب ‪ -‬حــد املســكر ‪ -‬أســباب مخففــة‬\n                                                                 ‫للعقوبــة ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى ( وتعانــوا علــى البــر والتقــوى وال تعاونــوا علــى اإلثــم‬\n                                                                         ‫والعــدوان )‪.‬‬\n                   ‫‪ -2‬املادة ‪ 38‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                   ‫‪ -3‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n      ‫‪ -4‬الفقــرة (‪ )1‬مــن املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                            ‫العقليــة‪.‬‬\n      ‫‪ -5‬الفقــرة (‪ )2‬مــن املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                            ‫العقليــة‪.‬‬\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا األول أجنبــي والثانــي ســعودي‬\n      ‫بشــرب املســكر وحيــازة احلشــيش بقصــد الترويج والتعاطــي وتعاطيهما‬\n      ‫لنوعهــا مــن الســابق ومحاولتهمــا الهــرب مــن رجــال األمــن والتســتر علــى‬\n      ‫الهــارب وطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بالســجن‬\n      ‫واجللــد والغرامــة وفــق األنظمــة والتعليمــات وإبعــاد األول عــن البــاد‬\n‫‪221‬‬\n\f‫ومنــع الثانــي مــن الســفر بعــد انتهــاء تنفيــذ العقوبــة واحلكــم عليهمــا‬\n‫بحــد املســكر ‪ ،‬حيــث قبــض علــى املدعــى عليهمــا إثــر ورود بــاغ عــن‬\n‫وجــود ثالثــة أشــخاص بداخــل حــوش وباالنتقــال للموقــع مت مشــاهدتهم‬\n‫داخــل احلــوش فحاولــوا الهــرب فتــم القبــض عليهمــا وبتفتيشــهما ضبــط‬\n‫مــع األول قطعــة بنيــة اللــون وتبــن أنهمــا بحالــة غيــر طبيعيــة وتنبعــث‬\n‫مــن أفواههمــا رائحــة املســكر وأثبــت التقريــر الكيميائــي الشــرعي‬\n‫إيجابيــة العينــة ملــادة احلشــيش املخــدر وأقــر املدعــى عليهمــا بشــرب‬\n‫املســكر وحيــازة احلشــيش بقصــد التعاطــي وأنكــرا احليــازة بقصــد‬\n‫الترويــج ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بســجن املدعــى‬\n‫عليهمــا ســنتني وجلدهمــا خمســن جلــدة مكــررة أربــع مــرات ودفــع‬\n‫غرامــة ماليــة قدرهــا ألــف ريــال علــى كل واحــد منهمــا ومنــع املدعــى‬\n‫عليــه الثانــي مــن الســفر خــارج اململكــة مــدة ســنتني بعــد انتهــاء‬\n‫تنفيــذ العقوبــة ‪،‬وبإبعــاد األول خــارج اململكــة وال يســمح لــه بالعــودة‬\n‫وإقامــة حــد املســكر عليهمــا بجلدهمــا ثمانــن جلــدة يف مــكان عــام‬\n‫وتعزيــر املدعــى عليهمــا بجلدهمــا ثالثــن جلــدة لقــاء محاولــة الهــرب‬\n‫وتســترهما علــى الهــارب وقنــع املدعــى عليهمــا واعتــرض املدعــي العــام‬\n                    ‫بالئحة‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n                                                                   ‫ُ‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة جــدة برقــم ‪ 34237103‬وتاريــخ‬\n‫‪ 1434/05/22‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341238668‬وتاريــخ‬\n‫‪ 1434/05/21‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/07/04‬هـ افتتحت‬\n                                                                                  ‫‪222‬‬\n\f      ‫اجللســة الســاعة ‪ 08 : 15‬وفيهــا حضــر املدعــي العــام ‪.....‬و أدعــي علــى‬\n      ‫كل مــن‪ )32(..... /1‬عام ـ ًا مينــي اجلنسي ــة ‪ ،‬مبوجــب البطاقــة البديلــة‬\n      ‫رقــم (‪ ).....‬عاطــل‪ ،‬متعلــم قبــض عليــه بتاريــخ ‪1434/3/25‬ه ـ وأودع‬\n      ‫بالســجن العــام مبحافظــة جــدة مبوجــب أمــر متديــد التوقيــف رقــم (‪).....‬‬\n      ‫وتاريــخ ‪1434/4/7‬ه ـ اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n      ‫‪1428/7/9‬هــ‪ )27(..... /2‬عام ـ ًا ســعودي اجلنسي ــة مبوجــب الســجل‬\n      ‫املدنــي رقــم (‪ ).....‬طالــب متعلــم ‪ ،‬قبــض عليــه بتاريــخ ‪1434/3/25‬ه ـ‬\n      ‫وأودع بالســجن العــام مبحافظــة جــدة مبوجــب أمــر متديــد التوقيــف رقــم‬\n      ‫(‪ ).....‬وتاريخ ‪1434/4/2‬هـ استناد ًا للقرار الوزاري رقم (‪ )1900‬وتاريخ‬\n      ‫‪1428/7/9‬ه ـ فبتاريــخ ‪1434/3/25‬ه ـ مت القبــض علــى املدعــى عليهما‬\n      ‫مــن قبــل رجــال الضبــط أثــر ورود إخباريــة عــن وجــود ثالثــة أشــخاص‬\n      ‫بداخــل حــوش يف شــارع التحليــة وباالنتقــال للموقــع مت مشــاهدتهم‬\n      ‫بداخــل احلــوش فحاولــوا الهــرب ومت القبــض علــى املدعــى عليهمــا‬\n      ‫وبتفتيشــهما ضبــط مــع األول بداخــل ســرواله الداخلــي قطعــة بنيــة‬\n      ‫اللــون بلــغ وزنهــا اإلجمالــي (‪ )134.7‬مائــة وأربعــة وثالثــون جرام ًا وســبعة‬\n      ‫أعشــار اجلــرام وتبــن أنهمــا بحالــة غيــر طبيعيــة وتنبعــث مــن أفواههمــا‬\n      ‫رائحــة املســكر وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪).....‬‬\n      ‫لعــام ‪1434‬ه ـ احتــواء عينــة الكميــة املضبوطــة واملرســلة للتحليــل علــى‬\n      ‫مــادة احلشــيش املخــدر واملدرجــة باجلــدول رقــم ( ‪ ) 1‬فئــة ( أ) وامللحــق‬\n      ‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبســماع أقــوال األول‪/‬‬\n      ‫أقــر بحيازتــه للقطعــة املضبوطــة معــه وأنــه اشــتراها مــع الثانــي بقصــد‬\n      ‫التعاطــي وتعاطــى منهــا وتعاطيــه لنوعهــا مــن الســابق وباســتجواب‬\n      ‫األول‪ /‬اعتــرف بشــرب املســكر وأفــاد بــأن قطعــة احلشــيش تعــود للثانــي‬\n\n\n‫‪223‬‬\n\f‫وأن الكميــة ضبطــت بداخــل مالبســه الداخليــة وباســتجواب الثانــي‪/‬‬\n‫أقــر بأنــه كان بحالــة ســكر عنــد القبــض عليــه‪ ،‬وأن الكميــة‬\n‫املضبوطــة تعــود إليــه وأنــه اشــتراها مــن شــخص بحــي ‪.....‬وقــد انتهــى‬\n‫التحقيــق إلــى توجيــه االتهــام لألول‪...../‬والثانــي‪ ،...../‬بشــرب املســكر‬\n‫وحيــازة (‪ )134.7‬مائــة وأربعــة وثالثــون جرام ـ ًا وســبعة أعشــار اجلــرام‬\n‫مــن احلشــيش املخــدر بقصــد الترويــج والتعاطــي وتعاطيهمــا لنوعهــا‬\n‫مــن الســابق اســتناد ًا للفقــرة (‪ )2‬مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة ومحاولتهمــا الهــرب عنــد القبــض عليهمــا‬\n‫والتســتر علــى هــارب‪ ،‬وذلــك لألدلــة والقرائــن التالية‪/1‬مــا ورد يف‬\n‫أقــوال األول مبلــف ســماع األقــوال لفــة رقم(‪)9-6‬وأقــوال الثانــي مبلــف‬\n‫االســتجواب املرفــق لفــة رقــم ( ‪/2) 36‬مــا ورد بشــهادة الشــهود الــواردة‬\n‫مبحضــر الضبــط املنــوه عنــه لفــة (‪/3)1‬مــا ورد بالتقريــر الكيميائــي‬\n‫الشــرعي املنــوه عنــه املرفــق لفــة (‪/4) 27‬مــا ورد يف محضــر اإلستشــمام‬\n‫املنــوه عنــه لفــة رقــم(‪ /5) 2‬كبــر الكميــة املضبوطــة وتواجدهمــا يف‬\n‫ســاعة متأخــرة مــن الليــل قرينــة قويــه علــى قــوة االتهــام املوجــه إليهمــا‬\n‫وباالطــاع علــى صحيفــة ســوابقهما عثــر لــأول علــى أربــع ســوابق‬\n‫(األولــى خطــف والثانيــة اعتــداء وخطــف وعــودة بعــد إبعــاد والثالثــة‬\n‫شــرب وحيــازة املســكر والرابعــة عــودة بعــد إبعــاده ) مســجله عليــه‬\n‫ولــم يعثــر للثانــي علــى ســوابق مســجلة عليــه وحيــث إن مــا أقدمــا عليــه‬\n‫املدعــى عليهمــا فعــل محــرم شــرع ًا ومجــرم نظامـ ًا طبقـ ًا للمــادة الثالثــة‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n‫امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ واملعاقــب عليهــا اســتناد ًا‬\n‫للمادتــن (‪ )41،38‬مــع مراعــاة مــا ورد باملــادة (‪ )62‬مــن ذات النظــام‬\n\n\n                                                                                      ‫‪224‬‬\n\f      ‫لــذا اطلــب إثبــات إدانتهمــا مبــا نســب إليهمــا ومعاقبتهمــا بالعقوبــات‬\n      ‫األصليــة والتكميليــة التاليــة أوالً‪ /‬بالســجن واجللــد والغرامــة اســتناد ًا‬\n      ‫للفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام املخــدرات املشــار إليــه ثالث ـ ًا ‪/‬‬\n      ‫إبعــاد األول بعــد انتهــاء تنفيــذ عقوبتــه وعــدم الســماح لــه بالعــودة إليهــا‬\n      ‫ومنــع الثانــي مــن الســفر خلــارج اململكــة بعــد انتهــاء تنفيــذ عقوبتــه وفقـ ًا‬\n      ‫للفقرتــن (‪ )2،1‬مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه كمــا أطلــب‬\n      ‫احلكــم عليهمــا بحــد شــرب املســكر‪ ،‬وتعزيرهمــا لقــاء محاولــة الهــرب‬\n      ‫عنــد القبــض عليهمــا والتســتر علــى هــارب‪ ،‬والتشــديد علــي األول يف‬\n      ‫العقوبــة لتعــدد ســوابقه التــي لــم تردعــه عقوباتهــا اســتنادا لتعميــم‬\n      ‫صاحــب الســمو امللكــي نائــب وزيــر الداخليــة رقــم (‪)93958/5/5/1‬‬\n      ‫واســالهم اإلجابــة وباســتجواب األول والثانــي أقــر بشــرب املســكر‬\n      ‫وحيــازة ‪ 134.7‬مائــة وأربعــة وثالثــون جرامــا وســبعة أعشــار اجلــرام مــن‬\n      ‫احلشــيش بقصــد التعاطــي وانكــرا احليــازة بقصــد الترويــج وبســؤال‬\n      ‫املدعــي العــام عــن البينــة اســتعد بإحضارهــا ورفعــت اجللســة إلحضــار‬\n      ‫البينــة وبــاهلل التوفيــق حــرر يف ‪1434/07/04‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد‬\n      ‫فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة مبحافظــة جــدة والقائــم‬\n      ‫بعمــل فضيلــة القاضــي ‪.....‬ففــي يــوم االثنــن املوافــق‪ 1434/08/08‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 12 : 00‬وفيهــا حضــر املدعــي العــام وبســؤاله‬\n      ‫عــن الشــهادة احضــر كال مــن ‪...../1 :‬ســعودي اجلنســية ســجل رقــم‬\n      ‫‪.....‬و‪.....‬ســعودي ســجل رقــم ‪.....‬و‪..... .....‬ســعودي اجلنســية ســجل رقــم‬\n      ‫‪.....‬احــد افــراد درويــات شــمال جــدة وشــهدوا قائلــن نشــهد بــاهلل‬\n      ‫تعالــى انــه يوجــد بــاغ مــن غرفــة العمليــات يف الوقــت احملــدد اعــاه‬\n      ‫بوجــود ثالثــة اشــخاص بداخــل احلــوش وعنــد مالحظتهــم للدوريــات مت‬\n\n\n‫‪225‬‬\n\f‫هروبهــم ولكــن باملتابعــة مــن الدوريــات مت ضبــط الشــخصني املوضحــة‬\n‫أســماءهم وهــروب الشــخص الثالــث وعنــد تفتيشــهم وجــد مــع املدعــو‬\n‫‪..........‬وصلــة بينــة اللــون يحتمــل ان تكــون مــن احلشــيش املخــدر وتــزن‬\n‫حوالــي مائــة وأربعــة وثالثــون جــزء مــن اجلــرام (‪ )134.7‬وجــوال بــاك‬\n‫بيــري لــون اســود وقــد وجــدت املــادة بداخــل الســروال الداخلــي وبتفتيــش‬\n‫الشــخص الثانــي وجــد جــوال بــاك بيــري اســود تــورش وعنــد ســؤالهم‬\n‫عــن الشــخص الثالــث أفــادوا بانهــم ال يعرفونــه وعلمــا أن األشــخاص‬\n‫تنبعــث منهــم رائحــة كريهــة يحتمــل أن تكــون رائحــة املســكر وهــم‬\n‫يف حالــة غيــر طبيعيــة هــذا مــا لدينــا مــن شــهادة وبهــا نشــهد وبعــرض‬\n‫الشــهادة علــى املدعــى عليهمــا تأجلــت إلــى يــوم األربعــاء ‪1434/8/10‬ه ـ‬\n‫الســاعة ‪ 09: 00‬وصلــى اهلل علــى نبينــا محمــد حــرر يف ‪1434/8/8‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة ففــي يــوم األربعــاء املوافــق‪ 1434/08/10‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 11 : 45‬وفيهــا حضــر املدعــي العــام وحضــر حلضــوره‬\n‫املدعــى عليهمــا ‪.....‬و ‪.....‬وبعــرض الشــهادة عليهمــا قــاال صحيــح مــا جــاء‬\n‫بشــهادة الشــهود ونحــن تائبــن إلــى اهلل عــز وجــل ذلــك كلــة فقــد ثبــت‬\n‫لــدي إدانتهمــا مبــا نســب إليهمــا جملــة وتفصيــا وبالرجــوع إلــى أوراق‬\n‫املعاملــة وجــدت التقريــر الكيميائــي الشــرعي رقم‪.....‬لعــام ‪1434‬ه ـ‬\n‫الحتــواء الكميــة املضبوطــة علــى مــادة احلشــيش املخــدر وبالرجــوع إلــى‬\n‫صحيفــة ســوابقهما عثــر علــى األول اربــع ســوابق األولــى خطــف والثانيــة‬\n‫اعتــداء وخطــف وعــودة بعــد إبعــاد والثالثــة شــرب وحيــازة املســكر‬\n‫والرابعــة عــودة بعــد إبعــاد ولــم يعثــر للثانــي علــى ســوابق ومبــا أن مــا قــام‬\n‫قبيحــا وجــرأة يف الباطــل‬\n                         ‫ً‬     ‫ا‬\n                               ‫محرمــا وفع ـ ً‬\n                                          ‫ً‬       ‫ا‬\n                                                  ‫بــه املدعــى عليهمــا يعــد عم ـ ً‬\n\n\n                                                                                           ‫‪226‬‬\n\f      ‫يســتحق العقــاب عليــه ومبــا أن ترويــج ذلــك فيــه نشــر للفســاد أوســاط‬\n      ‫املجتمــع وهــو مــن التعــاون علــى اإلثــم والعــدوان واهلل يقــول (وتعاونــوا‬\n      ‫علــى البــر والتقــوى وال تعاونــوا علــى اإلثــم والعــدوان) وملــا فيهــا مــن‬\n      ‫إضــرار بنفــس اإلنســان وعقلــه والواجــب عليــه حفظهمــا والشــريعة‬\n      ‫اإلســامية جــاءت بحفــظ الضروريــات اخلمــس ومنهــا حفــظ النفــس‬\n      ‫والعقــل والنتشــار هــذه احملظــورات يف أوســاط املجتمــع وهــذا يســتوجب‬\n      ‫األخــذ علــى مــن يقــوم بترويجهــا بحــزم وتطبيــق املــادة رقــم (‪ )38‬مــن‬\n      ‫نظــام مكافحــة املخــدرات املشــار إليــه ومبــا أن املدعــى عليهمــا أظهــر‬\n      ‫التوبــة والنــدم والعــزم علــى عــدم العــودة لفعلــه ولقلــة الســوابق املســجلة‬\n      ‫عليهمــا ونظــرا لقلــة الكميــة التــي بحوزتــه وهــذا يخفــف عنهمــا العقوبة‬\n      ‫وفقــا للمــادة رقــم (‪ )60‬مــن نظــام مكافحــة املخــدرات املشــار إليــه‬\n      ‫ولكــون املدعــى عليــه األول أجنبــي وال فائــدة مــن إطالــة ســجنه إذ مالــه‬\n      ‫إلــى الترحيــل وذلــك كلــه أمــر يلحــظ ولكــون املدعــى عليــه يســتحق‬\n      ‫ووفقــا للمادتــن (‪ )56 -60‬مــن نظــام‬  ‫ً‬    ‫طبقــا للقواعــد الشــرعية‬\n                                                                          ‫العقوبــة ً‬\n      ‫مكافحــة املخــدرات فلمــا ســبق فقــد حكمــت علــى املدعــى عليهمــا‬\n      ‫تعزيــر ًا مبــا يلــي‪ :‬أوالً‪ :‬يســجن املدعــى عليــه ملــدة ســنتني يحتســب منهــا‬\n      ‫مــا أمضيــاه موقوفــان يف هــذه القضيــة وجلدهــم خمســن جلــدة مكــررة‬\n      ‫اربعــة مــرات بينهــن مــدة ال تقــل عــن خمســة أيــام ويدفــع كل واحــد‬\n      ‫منهــم غرامــة ماليــة قدرهــا ‪1000‬ريــال لــكل واحــد منهمــا وفقــا للمــادة‬\n      ‫رقــم (‪ )60‬مــن النظــام املشــار إليــه املتضمنــة حــق النــزول عــن مقتضــى‬\n      ‫املــادة رقــم (‪ )38‬مــن النظــام املشــار إليــه ثاني ـاً‪ :‬مينــع املدعــى عليــه‬\n      ‫الثانــي مــن الســفر خــارج اململكــة بعــد انتهــاء تنفيــذ محكوميتــه ملــدة‬\n      ‫ســنتني وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن نظــام مكافحــة‬\n\n\n‫‪227‬‬\n\f‫املخــدرات املشــار إليــه ثاني ـاً‪ :‬يبعــد املدعــى عليــه األول خــارج اململكــة‬\n‫وال يســمح لــه بالعــودة إليهــا إال وفــق تعليمــات احلــج والعمــرة وفقــا للفقــرة‬\n‫رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات املشــار‬\n‫إليــه رابعـاً‪ :‬إقامــة حــد املســكر علــى املدعــى عليهمــا بجلــد كل واحــد‬\n‫منهمــا ثمانــن جلــدة حــدا يف مــكان عــام ومفرقــة علــى بدنهمــا خامسـاً‪:‬‬\n‫تعزيرهمــا بجلدهمــا ثالثــن جلــدة لقــاء محاولــة الهــرب عنــد القبــض‬\n‫عليهمــا والتســتر علــى الهــراب وبعــرض احلكــم علــى الطرفــن قــرر‬\n‫القناعــة وقــرر املدعــي العــام معارضتــه علــى احلكــم مــع تقــدمي الئحــة‬\n‫اعتراضيــة فافهــم باحلضــور يــوم األربعــاء ‪1434/8/17‬ه ـ الســتالم‬\n‫نســخة مــن احلكــم فافهــم بنــص النظــام وجــرى النطــق باحلكــم يف‬\n‫يــوم األربعــاء املوافــق ‪1434/8/10‬ه ـ الســاعة ‪ 12 : 15‬وعلــى ذلــك جــرى‬\n          ‫التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســول اهلل ‪ ...‬وبعــد‪ :‬فقــد جــرى‬\n‫منــا نحــن قضــاة الدائــرة اجلزائيــة الســابعة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة برقــم ‪ 341238668‬وتاريــخ‬\n‫‪1434/12/22‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ ‪.....‬‬\n‫القاضــي باحملكمــة اجلزائيــة مبحافظة جــدة برقم ‪ 34294519‬وتاريخ‬\n‫‪1434/8/10‬ه ـ احملكــوم فيــه مبــا دون بباطــن القــرار ‪ ،‬املتضمــن‬\n‫دعــوى املدعــي العــام ضــد ‪. ....‬ورفيقــه املتهمــن يف مخــدرات وبدراســة‬\n‫القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة‬\n‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                   ‫وصحبــه وســلم ‪.‬‬\n\n\n                                                                                         ‫‪228‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":221,"source_page_end":228,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0a397fe6737c5055e28b8a1b55269b7e90549b133f8882c2204ffe9659c65b54","normalized_text_hash":"5db89c86665570ec62f9419631e215e76a68f06b458b5d6df216e336c21f651c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p221-34294519"},{"id":"780e7d9c-8fc2-5d25-83e1-ce4e94b28a40","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازة املسكر و احلشيش واحلبوب احملظورة بقصد االستعمال -هروب من رجال األمن -حد املسكر -تعزير بالسجن واجللد ومنع من السفر .","document_number":"34233436","case_number":"34245333","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/6","year":"1434","subject":"مسكر -شرب املسكر -حيازة املسكر و احلشيش واحلبوب احملظورة بقصد االستعمال -هروب من رجال األمن -حد املسكر -تعزير بالسجن واجللد ومنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك‪ 34233436:‬تاريخه‪1434/6/6:‬هـ‬\n                         ‫رقم الدعوى‪34245333:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34268964:‬تاريخه‪1434/07/16:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬حيــازة املســكر و احلشــيش واحلبــوب احملظــورة‬\n      ‫بقصــد االســتعمال ‪ -‬هــروب مــن رجــال األمــن ‪ -‬حــد املســكر ‪ -‬تعزيــر‬\n                                         ‫بالســجن واجللــد ومنــع مــن الســفر ‪.‬‬\n\n\n\n\n                  ‫‪ -1‬املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                  ‫‪ -2‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه‬\n      ‫بقصــد االســتعمال وحيــازة احلشــيش واحلبــوب احملظــورة املخــدرة بقصــد‬\n      ‫االســتعمال والهــروب مــن رجــال األمــن وصــدم دوريتهــم وطلــب إثبــات‬\n      ‫مــا أســند إليــه واحلكــم عليــه بحــد املســكر وعقوبــة الســجن واملنــع‬\n      ‫مــن الســفر وفــق األنظمــة والتعليمــات وتعزيــره لقــاء حيــازة املســكر‬\n      ‫والهــروب مــن رجــال األمــن وإلزامــه بدفــع قيمــة اخلســائر املاديــة ‪،‬حيــث‬\n      ‫أنــه أثنــاء قيــام فرقــة املكافحــة بعملهــا مبراقبــة منــزل أحــد املروجــن‬\n      ‫للمخــدرات لوحــظ ســيارة فتــم إيقافهــا ولوحــظ بهــا املدعــى عليــه‬\n      ‫ويرافقــه شــخص آخــر ثــم قــام املدعــى عليــه بالهــرب بالســيارة فتمــت‬\n      ‫متابعتــه ثــم قــام بصــدم الدوريــة فتــم إيقافــه بالقــوة فقــام املدعــى عليــه‬\n\n‫‪229‬‬\n\f‫بالنــزول ورمــي قــارورة حتــت ســيارته وقــاوم رجــال األمــن وبتفتيشــه لــم‬\n‫يعثــر معــه علــى شــيء وبالتوجــه إلــى مــا قــام برميــه وجد قارورة بها ســائل‬\n‫تنبعــث منــه رائحــة تشــبه رائحــة العــرق املســكر وبتفتيــش الســيارة عثــر‬\n‫علــى كيــس بداخلــه قطعتــن مــن مــادة احلشــيش وعلــى أربــع حبــوب مــن‬\n‫احلبــوب احملظــورة ‪،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة‬\n‫ملــادة احلشــيش املخــدر وملــادة اإلمفيتامــن ومــادة الكحــول املســكر‪،‬‬\n‫صــادق املدعــى عليــه علــى الدعــوى ماعــدا مقاومــة رجــال األمــن ‪،‬وبنــاء‬\n‫علــى مــا تقــدم حكمــت احملكمــة بجلــده حــد املســكر ثمانــن جلــدة‬\n‫أمــام مــأ مــن النــاس وتعزيــره بالســجن ســتة أشــهر لقــاء حيــازة احلبــوب‬\n‫احملظــورة بقصــد االســتعمال وجلــده بخمســن جلــده لقــاء حيــازة‬\n‫املســكر وهروبــه مــن رجــال األمــن وصدمــه للدوريــة ‪،‬ومنعــه من الســفر‬\n‫مــدة ســنتني بعــد انتهــاء عقوبــة الســجن ‪،‬ورد دعــوى املدعــي العــام بطلبــه‬\n‫إلــزام املدعــى عليــه بدفــع قيمــة اخلســائر املاديــة ألنــه ال صفــة لــه معتبــرة‬\n‫يف ذلــك ‪،‬قنــع املدعــى عليــه واعتــرض املدعــي العــام مكتفي ـ ًا بالئحــة‬\n                     ‫‪،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬          ‫الدعــوى ُ‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنا‪.....‬القاضــي يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ 34245333‬وتاريــخ ‪ 1434/05/27‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341294859‬وتاريــخ ‪ 1434/05/27‬ه ـ ففــي يــوم‬\n‫االثنــن ‪ 1434/06/05‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 00‬وفيهــا‬\n‫حضــر املدعــي العــام ‪.....‬مدعيـ ًا علــى احلاضــر معــه ‪.....‬ســعودي اجلنســية‬\n\n                                                                                          ‫‪230‬‬\n\f      ‫ا يف دعــواه عليــه ‪ :‬إنــه بتاريــخ‬   ‫مبوجــب الســجل املدنــي رقــم ‪.....‬قائ ـ ً‬\n      ‫‪1434/4/29‬ه ـ أثنــاء قيــام فرقــة مكافحــة املخــدرات بعملهــا املعتــاد‬\n      ‫ومراقبــة أحــد املنــازل املعــروف صاحبهــا بترويــج املخــدرات بحــي ‪.....‬‬\n      ‫بشــارع (‪ ).....‬ويف متــام الســاعة الواحــدة وخمســون دقيقــة مــن صبــاح‬\n      ‫يــوم االثنــن املوافــق أعــاه لوحــظ ســيارة مــن نــوع كامــري اللــون أزرق‬\n      ‫فــاحت حتمــل اللوحــة رقــم (‪ ).....‬توقفــت أمــام املنــزل املعنــي وبعــد حوالــي‬\n      ‫دقيقتــن حتركــت فتــم التســكير عليهــا مــن األمــام مــن قبــل الدوريــة‬\n      ‫الرســمية ولوحــظ بهــا شــخصان ثــم قــام الســائق بالهــرب والرجــوع‬\n      ‫للخلــف حوالــي ‪ 70‬م ومتــت متابعتــه ثــم قــام بتغييــر اجتــاه الســيارة وصــدم‬\n      ‫الدوريــة املدنيــة مــن جهــة الرفــرف األمامــي األميــن (مت معاجلــة حــادث‬\n      ‫الصــدم مــن قبــل اجلهــة املختصــة) ومت إيقافهمــا بالقــوة ثــم قــام الســائق‬\n      ‫بالنــزول ورمــي قــارورة حتــت ســيارته وقــاوم رجــال األمــن مقاومة شــديدة‬\n      ‫محــاوال الهــرب وعــدم ركــوب الدوريــة الرســمية فتمــت الســيطرة عليــه‬\n      ‫وأخــذ إثباتــه و أتضــح أنــه املتهــم‪..... /‬وبتفتيشــه لــم يعثــر معــه علــى أي‬\n      ‫ممنــوع وبالتوجــه إلــى مــا قــام برميــه وجــد قــارورة مــاء صحــة نــوع ‪.....‬‬\n      ‫ســعة ‪500‬مــل بهــا ســائل أكثــر مــن النصــف ينبعــث منــه رائحــة تشــبه‬\n      ‫رائحــة العــرق املســكر وبطلــب إثبــات الراكــب اتضــح أنــه‪(..... /‬مت‬\n      ‫حفــظ األوراق بحقــه اســتنادا للمــادة ‪ 62‬مــن نظــام االجــراءات اجلزائيــة)‬\n      ‫وبتفتيشــه لــم يعثــر معــه علــى أي ممنــوع وبتفتيــش الســيارة عثــر حتــت‬\n      ‫أقــدام الســائق علــى كيــس نايلــون شــفاف ملفــوف بداخلــه قطعتــن‬\n      ‫ســوداء اللــون مــن مــادة احلشــيش املخــدر بلــغ وزن القطعــة األولــى‬\n      ‫(‪ ) 2.700‬جرامــان وســبعمائة مليجــرام وبلــغ وزن القطعــة الثانيــة (‪)900‬‬\n      ‫تســعمائة مليجــرام وعلــى عــدد (‪ )4‬أربــع حبــات بيضــاء اللــون حتمــل‬\n\n\n‫‪231‬‬\n\f‫عالمــة القوســن مــن احلبــوب احملظــورة وباســتجواب املتهــم ‪ /‬أقــر بــأن‬\n‫قطــع احلشــيش املخــدر واحلبــوب احملظــورة والشــراب املســكر يعــود لــه‬\n‫بغــرض االســتعمال وليــس ملرافقــه أي عالقــة بهــا كمــا أقــر بشــرب‬\n‫املســكر وصــدم الدوريــة دون علمــه أنهــا رســمية وقــد أثبــت التقريــر‬\n‫الكيميائــي الشــرعي الصــادر مــن مركــز الســموم والكيميــاء بصحــة‬\n‫تبــوك رقــم (‪ ).....‬لعــام ‪434‬ه ــإيجابية العينــات املرســلة ملــادة احلشــيش‬\n‫املخــدر وهــو مــن املــواد املخــدرة املنــوه عنهــا يف اجلــدول األول فئــة (أ)‬\n‫بتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم ‪89400/19‬‬\n‫وتاريــخ ‪1426/10/25‬ه ـ و ملــادة االمفيتامــن املنبهــة احملظــورة وهــو مــن‬\n‫املؤثــرات العقليــة اخلاضعــة للرقابــة املنــوه عنهــا يف اجلــدول الثانــي فئــة‬\n‫(ب) بتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم ‪89400/19‬‬\n‫وتاريــخ ‪1426/10/25‬ه ـ وملــادة الكحــول االيثيلــي املســكر وقد انتهى‬\n‫التحقيــق إلــى اتهــام ‪.....‬بشــرب املســكر وحيازتــه بقصــد االســتعمال‬\n‫وحيــازة قطعتــن ســوداء اللــون مــن مادة احلشــيش املخدر بلــغ وزن القطعة‬\n‫األولــى (‪ ) 2.700‬جرامــان وســبعمائة مليجــرام وبلــغ وزن القطعــة الثانيــة‬\n‫(‪ )900‬تســعمائة مليجــرام وعــدد (‪ )4‬أربــع حبــات مــن احلبــوب احملتويــة‬\n‫علــى مــادة االمفيتامــن املنبهــة احملظــورة بقصــد االســتعمال والهــروب‬\n‫مــن رجــال األمــن وصــدم دوريتهــم وذلــك لألدلــة والقرائــن التاليــة ‪-1 :‬‬\n‫مــا جــاء بأقــوال املتهــم املدونــة علــى محضــر االســتجواب املرفــق لفــة‬\n‫رقــم ( ‪ -2 )8-7-6‬مــا جــاء يف محضــر القبــض والتفتيــش املــدون علــى‬\n‫الصفحــة رقــم (‪ )13-12‬مــن ملــف االســتدالل املرفــق لفــة رقــم (‪-3)1‬‬\n‫مــا جــاء يف التقريــر الكيمائــي الشــرعي املرفــق لفــه رقــم (‪ -4 )40‬مــا‬\n‫جــاء بالفواتيــر املرفقــة لفــة رقــم (‪ )38-35‬وحيــث ان مــا أقــدم عليــه‬\n\n\n                                                                                      ‫‪232‬‬\n\f      ‫املتهــم املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم‬\n      ‫شــرعا ومجــرم نظامــا بنــص الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n      ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ممــا يتعــن معــه إحالتــه إلــى احملكمــة‬\n      ‫املختصــة اســتنادا للمادتــن (‪ )128.126‬مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫بطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باالتــي‪ -1 :‬حــد‬\n      ‫املســكر لقــاء شــربه املســكر ‪ -2‬عقوبــة الســجن وفقــا للمــادة (‪)41‬‬\n      ‫الفقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات ‪ -3‬عقوبــة املنــع مــن الســفر‬\n      ‫خــارج اململكــة وفق ـ ًا للفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام نفســه‬\n      ‫‪ -4‬عقوبــة تعزيريــة لقــاء حيازتــه املســكر وهروبــه مــن رجــال األمــن‬\n      ‫وصــدم الدوريــة الرســمية ‪ -5‬إلــزام املتهــم بدفــع قيمــة اخلســائر املاديــة‬\n      ‫التــي احلقهــا بدوريــة املكافحــة حســب الفواتيــر املرفقــة (علمـ ًا أن احلــق‬\n      ‫اخلــاص لرجــال األمــن جــراء املقاومــة انتهــى بالتنــازل) وبالبحــث عــن‬\n      ‫ســوابقه عثــر لــه علــى ســابقتني مســجلتني ضــده األولــى والثانيــة شــرب‬\n      ‫املســكرات هكــذا ادعــى املدعــي العــام وبعــرض الدعــوى علــى املدعى‬\n      ‫عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه مــن قيامــي بشــرب‬\n      ‫املســكر وحيــازة بقصــد االســتعمال وحيــازة قطعتــن ســوداوي اللــون‬\n      ‫مــن مــادة احلشــيش املخــدر البالــغ وزن القطعــة األولى جرامان وســبعمائة‬\n      ‫مليجــرام ووزن القطعــة الثانيــة تســعمائة مليجــرام وعــدد أربــع حبــات‬\n      ‫مــن احلبــوب احملتويــة علــى مــادة االمفيتامــن املنبهــة احملظــورة بقصــد‬\n      ‫االســتعمال والتعاطي كله صحيح وبالنســبة لصدمي للدورية فصحيح‬\n      ‫حيــث لــم تكــن رســمية ولــم أعلــم بأنهــا رســمية وبالنســبة ملقاومــة رجــال‬\n      ‫األمــن فغيــر صحيــح هــذا جوابــي وبســؤال املدعــي العــام هــل لديــه بينــة‬\n\n\n‫‪233‬‬\n\f‫علــى مــا ادعــى بــه فقــال بينتــي مــا جــاء يف أوراق املعاملــة هكــذا أجــاب‬\n‫هــذا وباالطــاع علــى إقــرار املدعــى عليــه حتقيقـ ًا ومحضــر االســتجواب‬\n‫لفــة رقــم (‪6‬و‪7‬و‪ )8‬تضمــن اعترافــه بشــرب املســكر وحيازتــه لــه‬\n‫وكذلــك حيازتــه للحبــوب املذكــورة وأن غرضــه مــن حيــازة احلبــوب‬\n‫هــو االســتخدام هــذا وباالطــاع علــى التقريــر الكيميائــي الشــرعي‬\n‫لفــة رقــم (‪ )40‬وجدتــه يتضمــن إيجابيــة مــا مت ضبطــه للحشــيش املخــدر‬\n‫واالمفيتامــن املنبــه وبســؤاله عــن الســوابق أجــاب بــأن عليــه ســابقتني‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى اإلجابــة ومصادقــة املدعــى عليــه علــى‬\n‫دعــوى املدعــي العــام مــن قيامــه بشــرب املســكر وحيازتــه له االســتعمال‬\n‫ـاء‬\n‫وحيازتــه لقطعتــي احلشــيش واحلبــوب احملظــورة لقصــد االســتعمال وبنـ ً‬\n‫علــى اطالعــي علــى التقريــر الكيميائــي الشــرعي واملــواد النظاميــة‬\n‫املشــار إليهــا يف دعــوى املدعــي العــام لــذا كلــه فقــد ثبــت لــدي مــا اســند‬\n‫إلــى املدعــى عليــه يف دعــوى املدعــي العــام مــن شــربه للمســكر وحيازتــه‬\n‫لــه بقصــد االســتعمال وحيــازة قطعتــي احلشــيش وأربــع حبــات محظــورة‬\n‫مــن حبــوب االمفيتامــن املنبــه احملظــورة وصدمــة لســيارة الفرقــة‬\n‫القابضــة والهــروب منهــم وحكمــت مبــا يلــي أوال ‪ :‬جلــد املدعــى عليــه‬\n‫ثمانــن جلــدة حــد املســكر أمــام مــأ مــن النــاس لقــاء شــربه العــرق‬\n‫املســكر ثانيـ ًا ‪ :‬تعزيــر املدعــى عليــه وذلــك بســجنه ســتة أشــهر يحتســب‬\n‫منهــا مــدة إيقافــه علــى ذمــة هــذه القضيــة لقــاء حيازتــه احلبــوب احملظــورة‬\n‫لقصــد االســتعمال اســتناد ًا للمــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة ثالث ـ ًا ‪ :‬تعزيــر املدعــى عليــه وذلــك بجلــده خمســن‬\n‫جلــدة لقــاء حيازتــه للمســكر وهروبــه مــن رجــال األمن وصدمــه للدورية‬\n‫الرســمية رابعـ ًا ‪ :‬أفهمــت املدعــى عليــه مبنعــه مــن الســفر خــارج اململكــة‬\n\n\n                                                                                        ‫‪234‬‬\n\f      ‫ملــدة ســنتني تبــدأ بعــد انتهــاء عقوبــة الســجن اســتناد ًا للمــادة (‪ )56‬مــن‬\n      ‫نفــس النظــام خامس ـ ًا ‪ :‬رد دعــوى املدعــي العــام بطلبــه إلــزام املدعــي‬\n      ‫عليــه بدفــع قيمــة اخلســائر املاديــة التــي أحلقهــا بدوريــة املكافحــة ألنــه‬\n      ‫ال صفــة لــه معتبــرة يف ذلــك وبإعــان احلكــم قنــع بــه املدعــى عليــه وأمــا‬\n      ‫املدعــي العــام طلــب االســتئناف معتبــر ًا الئحــة الدعــوى الئحــة اعتــراض‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                              ‫حــرر يف ‪1434/6/5‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫الثانيــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف باجلــوف علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بعرعــر الشــيخ ‪.....‬‬\n      ‫برقــم ‪ 341294859‬وتاريــخ ‪1434/6/18‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلــة الشــيخ ‪ .....‬برقــم ‪ 34233436‬تاريــخ ‪1434/6/6‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد ‪ .....‬يف قضيــة مســكر وقــد تضمــن القــرار‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة تقــرر املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه‬\n      ‫علــى احلكــم مبنــع املدعــى عليــه مــن الســفر خــارج اململكــة و عــدم‬\n      ‫ال واهلل املوفــق‬  ‫االكتفــاء باإلفهــام حســب التعليمــات وذلــك مســتقب ً‬\n                       ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪235‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":229,"source_page_end":235,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1cef0960895049e71b3c505f48323b7baffb140139f86da031bbfeaf8b27d63f","normalized_text_hash":"f3b18e3b0a3f28ef93687753509d4a6313e8321f184923e1d0661c58f3ea1afa","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p229-34233436"},{"id":"43f99ef1-b07c-5a8f-b87f-2ba06142c9cb","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازته بقصد الشرب -أسباب مخففة للعقوبة -إذا اجتمع أمران من جنس واحد دخل أحدهما يف اآلخر -االكتفاء باحلد ودخول التعزير فيه .","document_number":"34253033","case_number":"34281909","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/27","year":"1434","subject":"مسكر -شرب املسكر -حيازته بقصد الشرب -أسباب مخففة للعقوبة -إذا اجتمع أمران من جنس واحد دخل أحدهما يف اآلخر -االكتفاء باحلد ودخول التعزير فيه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34253033:‬تاريخه‪1434/6/27:‬هـ‬\n                  ‫رقم الدعوى‪34281909:‬‬\n            ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34347598:‬تاريخه‪1434/11/03:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬حيازتــه بقصــد الشــرب ‪ -‬أســباب مخففــة‬\n‫للعقوبــة ‪ -‬إذا اجتمــع أمــران مــن جنــس واحــد دخــل أحدهمــا يف اآلخــر‬\n                            ‫‪ -‬االكتفــاء باحلــد ودخــول التعزيــر فيــه ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه تعالــى ( يأيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n    ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ‪.‬‬\n‫‪ -2‬قولــه تعالــى ( تلــك حــدود اهلل فــا تعتدوهــا ومــن يتعــد حــدود اهلل‬\n                                                  ‫فأولئــك هــم الظاملــون ) ‪.‬‬\n‫‪ -3‬عــن ابــن عمــر رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه وســلم‬\n‫قــال ( لعــن اهلل اخلمــر وشــاربها وســاقيها ومبتاعهــا وبائعهــا وعاصرهــا‬\n             ‫ومعتصرهــا وحاملهــا واحملمولــة إليــه ) أخرجــه أبــوداود ‪.‬‬\n‫‪ -4‬عــن ابــن عبــاس رضــي اهلل عنهمــا قــال ســمعت رســول اهلل صلــى اهلل‬\n‫عليــه وســلم يقــول ( أتانــي جبريــل فقــال يــا محمــد إن اهلل لعــن اخلمــر‬\n‫وعاصرهــا ومعتصرهــا وشــاربها واحملمولــة إليــه وبائعهــا ومبتاعهــا‬\n‫وســاقيها ومســقيها)أخرجه أحمــد وابــن حبــان يف صحيحــه واحلاكم‪.‬‬\n‫‪ -5‬عــن ابــن عمــر رضــي اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه وســلم‬\n‫قــال ( ثالثــة حــرم اهلل تبــارك وتعالــى اجلنــة مدمــن اخلمــر والعــاق‬\n                                  ‫والديــوث الــذي يقــر يف أهلــه اخلبــث ) ‪.‬‬\n\n                                                                                  ‫‪236‬‬\n\f      ‫‪ -6‬عــن جابــر بــن عبــداهلل رضــي اهلل عنــه أن رســول اهلل صلــى اهلل عليــه‬\n      ‫وســلم قال ( كل مســكر خمر إن اهلل عهد ملن يشــرب املســكر أن يســقيه‬\n                         ‫اهلل مــن طينــة اخلبــال ‪ )..‬أخرجــه مســلم يف صحيحــه ‪.‬‬\n      ‫‪ -7‬ذكــر ابــن القيــم يف زاد املعــاد ‪ ( 42/5‬ويف مصنــف عبدالــرزاق أنــه‬\n                               ‫صلــى اهلل عليــه وســلم جلــد يف اخلمــر ثمانــن ) ‪.‬‬\n      ‫‪ -8‬ذكــر املــرداوي يف اإلنصــاف ‪ ( 422 -421/26‬ومــن شــربه مختــار ًا‬\n      ‫ا كان أو كثيــر ًا فعليــه احلــد ثمانــون‬    ‫عامل ـ ًا أن كثيــره يســكر قلي ـ ً‬\n      ‫جلــدة وهــذا املذهــب وعليــه جماهيــر األصحــاب وجــزم بــه اخلرقــي‬\n                                                                    ‫وابــن عقيــل ) ‪.‬‬\n      ‫‪ -9‬مــا قــرره أهــل العلــم مــن عــدم اجلمــع بــن احلــد والتعزيــر قــال ابــن‬\n      ‫قدامــة ‪ ( 74/9‬مــا يوجــب احلــد مــن الزنــا والســرقة والقــذف وشــرب‬\n      ‫اخلمــر إذا تكــرر قبــل إقامــة احلــد أجــزأ حد واحد بغير خــاف علمناه)‪.‬‬\n      ‫‪ -10‬ذكــر العــز بــن عبدالســام يف كتابــه قواعــد األحــكام يف مصالــح‬\n      ‫األنــام ‪ ( 252/1‬والزجــر يحصــل بتعــدد األســباب وأولــى الواجبــات‬\n                                                             ‫بالتداخــل احلــدود) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه‬\n      ‫بقصــد الشــرب ‪،‬وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد‬\n      ‫املســكر وتعزيــره لقــاء احليــازة ‪،‬حيــث قبــض علــى املدعــى عليــه مــن‬\n      ‫قبــل إحــدى فــرق الدوريــات األمنيــة لالشــتباه بــه واتضــح أنــه بحالــة غيــر‬\n      ‫طبيعيــة وضبــط بحوزتــه قارورتــن بهمــا مســكر وباستشــمامه تبــن أن‬\n      ‫رائحــة املســكر تفــوح مــن فمــه ‪،‬وأثبــت التقريــر الكيميائــي الشــرعي‬\n\n‫‪237‬‬\n\f‫إيجابيــة العينــة املضبوطــة ملــادة الكحــول ‪،‬وصــادق املدعــى عليــه علــى‬\n‫الدعــوى وأبــدى النــدم والتوبــة ‪ ،‬وملــا قــرره أهــل العلــم مــن دخــول العقوبــة‬\n‫التعزيريــة يف احلــد ‪ ،‬وصغــر ســن املدعــى عليــه ‪،‬وبنــاء علــى مــا تقــدم‬\n‫حكمــت احملكمــة بجلــده ثمانــن جلــدة حــد املســكر دفعــة واحــدة‬\n‫وصــرف النظــر عــن تعزيــره للحيــازة لعــدم توفــر موجبــه ولقلــة الكميــة‬\n‫‪،‬وقنــع املدعــى عليــه باحلكــم ‪،‬واعتــرض املدعــي العــام مكتفي ـ ًا‬\n          ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬         ‫بالئحــة الدعــوى ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 34281909‬وتاريــخ ‪ 1434/06/19‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341481878‬وتاريــخ ‪1434/06/19‬ه ـ ففــي يــوم‬\n   ‫الثالثــاء املوافــق‪ 1434/06/27‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 00‬‬\n‫للنظــر يف الدعــوى املقامــة مــن املدعــي العــام ضــد ‪.....‬بدعــوى شــرب‬\n‫مســكر‪،‬وفيها حضــر املدعــي العــام ‪.....‬وحضــر حلضــوره‪..... :‬‬\n‫العمر‪26‬عام ـ ًا ‪ ،‬اجلنســية ســعودي ‪ ،‬رقــم الهويــة (‪ ).....‬يقيــم مبدينــة‬\n       ‫الريــاض ‪ ،‬مفــرج عنــه بالكفالــة احلضوريــة قائــا يف دعــواه‪:‬‬\n‫أنــه بتاريخ‪1434/3/20‬ه ـ قبــض علــى املذكــور مــن قبــل إحــدى فــرق‬\n‫الدوريــات األمنيــة لالشــتباه بــه واتضــح انــه بحالــه غيــر طبيعيــة وضبــط‬\n‫بحوزتــه قارورتــن بهمــا مســكر وباستشــمامه تبــن أن رائحــة املســكر‬\n‫تفــوح مــن فمــه ‪ ،‬واثبــت التقريــر الكيميائــي الشــرعي رقــم (‪).....‬‬\n\n                                                                                         ‫‪238‬‬\n\f      ‫إيجابيــة مــا ضبــط للكحــول ‪،‬وباســتجوابه اعتــرف بشــرب املســكر‬\n      ‫وحيازتــه ‪ ،‬وأســفر التحقيــق عــن اتهــام املدعــى عليــه بشــرب املســكر‬\n                         ‫وحيازتــه بقصــد شــربه وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n                                                          ‫‪ -1‬ما جاء يف أقواله لفه (‪)1‬‬\n                                            ‫‪ -1‬محضر االستشمام املنوه عنه لفة (‪)1‬‬\n                                                ‫‪ -3‬محضر القبض املنوه عنه لفه (‪)2‬‬\n                                 ‫‪ -4‬التقرير الكيميائي الشرعي املنوه عنه لفه(‪)6‬‬\n                          ‫وببحث سوابقه أتضح عدم وجود سوابق مسجلة ضده‬\n      ‫وحيــث أن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر وبعقوبــة‬\n                   ‫تعزيريــة حليازتــه املســكر وبــاهلل التوفيــق ‪ ،‬هــذه دعــواي‪،‬‬\n      ‫وبســؤال املدعــى عليــه عــن دعــوى املدعــي العــام أجــاب قائــا‪ :‬كل مــا‬\n      ‫ذكــره املدعــي العــام مــن أنــه قــد قبــض علــي يف ‪ 1434/3/20‬مــن قبــل‬\n      ‫إحــدى فــرق الدوريــات األمنيــة وأنــا بحالــة غيــر طبيعيــة وضبــط بحوزتــي‬\n      ‫قارورتــن بهمــا مســكر‪ ،‬ورائحــة املســكر تفــوح مــن فمــي فهــذا كلــه‬\n      ‫صحيــح‪ ،‬وقــد شــربت املســكر وأغوانــي الشــيطان يف ذلــك‪ ،‬وأنــا واهلل‬\n      ‫تائــب ونــادم وأرجــو مــن اهلل العفــو والغفــران‪ ،‬هكــذا أجاب‪،‬فجــرى‬\n      ‫ســؤاله مــا ســبب حيازتــك للقارورتــن؟ فقــال‪ :‬ســبب حيازتــي لهاتــن‬\n      ‫القارورتــن‪ :‬للشــرب‪ ،‬هكــذا قــرر‪ ،‬هــذا كمــا جــرى االطــاع علــى‬\n      ‫املعاملــة علــى لفــة رقــم ‪ 6‬وهــو تقريــر كيميائــي شــرعي برقــم ‪.....‬‬\n      ‫مبوجــب خطــاب مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة‬\n      ‫الشــرعية برقــم ‪.....5013‬يف ‪ 1434/5/1‬ونــص احلاجــة منــه‪« :‬ثبــت لدينــا‬\n      ‫اآلتــي‪ :‬أوال‪ :‬املرســل األول عبــارة عــن قــارورة مــاء صحــة ‪.....‬ســعة ‪500‬‬\n\n\n‫‪239‬‬\n\f‫مــل‪ ،‬بهــا ســائل حجمــه ‪ 190‬مــل ثبــت إيجابيتــه ملــادة الكحــول بنســبة‬\n‫‪ . %15‬ثانيــا‪ :‬املرســل الثانــي عبــارة عــن قــارورة مــاء صحــة ‪.....‬ســعة ‪1.5‬‬\n‫لتــر بهــا ســائل حجمــه ‪ 180‬مــل ثبــت إيجابيتــه ملــادة الكحــول بنســبة‬\n                           ‫‪ %40‬وقــد اســتهلكت العينتــن يف التحليــل» أ‪.‬هــ‪.‬‬\n‫هــذا كمــا جــرى االطــاع علــى لفــة رقــم ‪ 2‬وهــو تقريــر أولــي معــد‬\n‫ومســلم مــن قبــل الفرقــة‪ ،‬برقــم ‪.....‬يف ‪ 1434/3/20‬ونــص احلاجــة منــه‪:‬‬\n‫«الحظــت الشــخص املذكــور أعــاه داخــل احلــي وعنــد النــزول عنــده‬\n‫وتفتيشــه وجــد بحوزتــه قارورتــن أحدهــا أبــو ثــاث ريــال بهــا النصــف‬\n‫والثانيــة أبــو ريــال بهــا النصــف وهــو بحالــة غيــر طبيعيــة (ســكر)» أ‪.‬هــ‪.‬‬\n‫فجــرى ســؤال املدعــى عليــه مــا ســبب حيازتــك للمســكر فقــال‪ :‬هــي‬\n‫للشــرب وقــد قبــض علــي وهــي بحوزتــي وكنــت أشــرب مــن أحــد‬\n‫القارورتــن التــي كانتــا معــي‪ ،‬هكــذا قــرر‪ ،‬فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وملصادقــة املدعــى عليــه علــى دعــوى املدعــي العــام وال‬\n‫عــذر ملــن أقــر ومبــا أن الكميــة التــي مســكت مــع املدعــى عليــه قليلــة‬\n‫جــدا‪ ،‬ومبــا أنــه كانــت بحوزتــه وقــت التعاطــي ويشــرب مــن أحدهمــا‬\n‫وقــد قــرر العلمــاء رحمهــم اهلل بــأن العقوبــة التعزيريــة داخلــة يف احلــد‬\n‫ولصغــر ســن املدعــى عليــه ومبــا أنــه ليــس عليــه ســوابق ومبــا أنــه ظهــر‬\n‫لنــا توبتــه وندمــه علــى مــا مضــى وقــد قــال اهلل عــز وجــل «يــا أيهــا الذيــن‬\n‫آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان‬\n‫فاجتنبــوه لعلكــم تفلحــون»‪ ،‬ويف احلديــث عــن ابــن عمــر رضــي اهلل‬\n‫عنهمــا أن النبــي صلــى اهلل عليــه وســلم قــال‪« :‬لعــن اهلل اخلمــر وشــاربها‬\n‫وســاقيها ومبتاعهــا وبائعهــا وعاصرهــا ومعتصرهــا وحاملهــا واحملمولــة‬\n‫إليــه» أخرجــه أبــو داود‪ ،‬وعــن ابــن عبــاس رضــي اهلل عنهما قال‪ :‬ســمعت‬\n\n\n                                                                                          ‫‪240‬‬\n\f      ‫رســول اهلل صلــى اهلل عليــه وســلم يقــول‪« :‬أتانــي جبريــل فقــال يــا محمــد‬\n      ‫إن اهلل لعــن اخلمــر وعاصرهــا ومعتصرهــا وشــاربها واحملمولــة إليــه‬\n      ‫وبائعهــا ومبتاعهــا وســاقيها ومســقيها» أخرجــه أحمــد بإســناد صحيــح‪،‬‬\n      ‫وابــن حبــان يف صحيحــه واحلاكــم‪ ،‬وعــن عبــداهلل بــن عمــر رضــي اهلل‬\n      ‫عنهمــا أن الرســول صلــى اهلل عليــه وســلم قــال‪« :‬ثالثــة حــرم اهلل تبــارك‬\n      ‫وتعالــى اجلنــة‪ :‬مدمــن اخلمــر‪ ،‬والعــاق‪ ،‬والديــوث الــذي يقــر يف أهلــه‬\n      ‫اخلبــث»‪ ،‬وقــد انعقــد اإلجمــاع علــى أن اخلمــر حــرام شــربه واســتعماله‬\n      ‫كيفمــا كان االســتعمال‪ ،‬وذلــك ممــا علــم مــن الديــن بالضــرورة‪،‬‬\n      ‫وعــن جابــر بــن عبــداهلل أن رســول اهلل صلــى اهلل عليــه وســلم قــال‪« :‬كل‬\n      ‫مســكر خمــر‪ ،‬إن اهلل عهــد ملــن يشــرب املســكر أن يســقيه مــن طينــة‬\n      ‫اخلبــال‪ ،‬قالــوا يــا رســول اهلل مــا طينــة اخلبــال؟ قــال‪ :‬عــرق أهــل النــار»‬\n      ‫أخرجــه مســلم يف صحيحــه‪ ،‬وقــد ذكــر ابــن القيــم رحمــه اهلل تعالــى يف‬\n      ‫كتابــه زاد املعــاد ‪ 42/5‬مــا نصــه‪« :‬ويف مصنــف عبدالــرزاق أنــه صلــى‬\n      ‫اهلل عليــه وســلم جلــد يف اخلمــر ثمانــن» أ‪.‬هــ‪ .‬وقــد ذكــر املــرداوي يف‬\n      ‫كتابــه اإلنصــاف ‪ 422-421/26‬مــا نصــه‪« :‬ومــن شــربه مختــارا عاملــا‬\n      ‫أن كثيــره يســكر قليــا كان أو كثيــرا فعليــه احلــد ثمانــون جلــدة‬\n      ‫وهــذا املذهــب وعليــه جماهيــر األصحــاب‪ ،‬وجــزم بــه اخلرقــي وابــن‬\n      ‫عقيــل» أ‪.‬هــ‪ .‬فعليــه فقــد ثبــت لــدي إدانــة املدعــى عليــه بشــرب املســكر‬\n      ‫وحيازتــه قارورتــن بقصــد الشــرب‪ ،‬جلميــع ذلــك فقــد حكمــت باآلتــي ‪:‬‬\n      ‫أوال‪ :‬بصــرف النظــر عمــا طلبــه املدعــي العــام مــن تعزيــر املدعــى عليــه‬\n      ‫حليازتــه املســكر‪ ،‬لعــدم توفــر موجبــه‪ ،‬ولقلــة الكميــة وقــد مت القبــض‬\n      ‫عليــه وهــو يف حالــة ســكر‪ ،‬ويشــرب مــن أحدهمــا‪ .‬ثانيــا‪ :‬بجلــد املدعــى‬\n      ‫عليــه ‪.....‬ثمانــن جلــدة دفعــة واحــدة‪ ،‬وهــي حــد املســكر وبعرضــه علــى‬\n\n\n‫‪241‬‬\n\f‫املدعــى عليــه قنــع بــه‪ ،‬وقــرر املدعــي العــام اعتراضــه علــى احلكــم‪،‬‬\n‫واكتفائــه بالئحــة الدعــوى العامــة عــن الالئحــة االعتراضيــة وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                       ‫حــرر يف ‪1434/06/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم اخلميــس ‪ 1434/09/17‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 : 40‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مــن الدائــرة اجلزائيــة األولــى بالقــرار رقــم ‪ 34302035‬يف ‪1434/8/22‬‬\n‫واملقيــدة يف احملكمــة برقــم ‪ 341645200‬يف ‪ 1434/9/8‬واملتضمــن‬\n                                                                          ‫مــا نصــه‪:‬‬\n‫«وانتهــاء الدراســة والتدقيــق مبالحظــة مــا يلــي‪ :‬قــرر فضيلــة ناظــر‬\n‫القضيــة حفظــه اهلل وســدده صــرف النظــر فيمــا يختــص بعقوبــة احليــازة‬\n‫وهــذا غيــر مســلم إذ أن فضيلتــه أثبــت إدانتــه بــه‪ ،‬واملتعــن تقريــر عقوبــة‬\n‫تعزيريــة لقــاء ذلــك‪ ،‬فعلــى فضيلتــه مالحظــة ذلــك‪ ،‬وإحلــاق مــا يجــد‬\n‫يف الضبــط وصورتــه والقــرار وســجله‪ .‬قاضــي اســتئناف‪(..... :‬املصادقــة‬\n‫علــى احلكــم) موقــع علــى األصــل‪ ،‬مجــاز‪ ،‬قاضــي اســتئناف‪،..... :‬‬\n                 ‫ختمــه توقيعــه‪ ،‬رئيــس الدائــرة‪ ،..... :‬ختمــه توقيعــه» أ‪.‬هــ‪.‬‬\n‫فعليــه أجيــب صاحبــي الفضيلــة مســتعينا بــاهلل عــز وجــل ووفقنــي اهلل‬\n‫وإياهــم ملــا يحــب ويرضــى أنــه ال يخفــى علــى شــرف علمهــم أن املســألة‬\n‫خالفيــة‪ ،‬وفيهــا قــوالن ألهــل العلــم‪ :‬القــول األول‪ :‬كمــا ذكــر صاحبــي‬\n‫الفضيلــة‪ ،‬والقــول اآلخــر‪ :‬قــد ذكــروا بأنــه ال يصــح إفــراد املقدمــات‬\n               ‫الالحقــة بعقوبــة مســتقلة عــن احلــد‪ ،‬وقــد اســتدلوا مبــا يلــي‪:‬‬\n‫‪ )1‬أن املقدمــات الســابقة ال تفــرد‪ ،‬فكــذا الالحقــة‪ ،‬إذ ال فــرق‪،‬‬\n                                                             ‫فكالهمــا مقدمــة‪.‬‬\n\n\n                                                                                        ‫‪242‬‬\n\f      ‫‪ )2‬أن العقوبــة ردعــا عــن إتيــان احلــد‪ ،‬فــإذا وقــع فيــه لــم يكــن بإفــراد‬\n                                               ‫أحدهمــا بالعقوبــة معنــى شــرع لهــا‪.‬‬\n      ‫‪ )3‬وألن املقدمــات ســواء كانــت ســابقة للحــد أو الحقــة لــه ال تعــدو‬\n      ‫أن تكــون معصيــة صغــرى ومعصيــة كبــرى‪ ،‬وإذا اجتمعــت معصيتــان‬\n      ‫مــن جنــس واحــد صغــرى وكبــرى دخلــت عقوبــة الصغــرى يف عقوبــة‬\n                                                          ‫الكبــرى الرتــكاب احلــد‪.‬‬\n      ‫‪ )4‬أن الــردع متحقــق يف دمــج العقوبــة وتوحيدهــا‪ ،‬واملقصــود مــن‬\n      ‫العقوبــات الزجــر‪ ،‬وألن مبنــى العقوبــات علــى التداخــل‪ ،‬فالزنــا الواحــد‬\n      ‫غالبــا مــا يتضمــن عــدة زنيــات ‪ ،‬فــكل إيالجــة يف الفــرج انفــردت‬\n      ‫موجبــة للحــد‪ ،‬وكذلــك الســكر فإنــه يتضمــن حســوات‪ ،‬كل واحــدة‬\n      ‫منهــا موجبــة للحــد لــو انفــردت‪ ،‬فقــد تداخلــت ولئــن تتداخــل املقدمــات‬\n                                                       ‫ولــو فصــل بينهمــا حــد أولــى‪.‬‬\n      ‫‪ )5‬وقــد ذكــر العــز بــن عبدالســام رحمــه اهلل تعالــى يف كتابــه قواعــد‬\n      ‫األحــكام يف مصالــح األنــام ‪ 252/1‬مــا نصــه‪« :‬والزجــر يحصــل بتعــدد‬\n                              ‫األســباب وأولــى الواجبــات بالتداخــل احلــدود» أ‪.‬هــ‪.‬‬\n      ‫‪ )6‬ال يخفــى علــى أصحــاب الفضيلــة القاعــدة الفقهيــة‪ :‬إذا اجتمــع أمران‬\n      ‫مــن جنــس واحــد ولــم يختلــف مقصودهمــا دخــل أحدهمــا يف اآلخــر‪،‬‬\n                         ‫ذكــر هــذه القاعــدة ابــن جنيــم والســبكي والســيوطي‪.‬‬\n      ‫‪ )7‬القاعــدة الفقهيــة أنــه ال يفــرق بــن متماثلــن‪ ،‬وال يســاوى بــن‬\n                                                                              ‫مختلفــن ‪.‬‬\n      ‫‪ )8‬وألنــه ال مدخــل للمصالــح املرســلة يف احلــدود واملقــدرات‪ ،‬وقــد قــال‬\n      ‫اهلل عــز وجــل‪« :‬تلــك حــدود اهلل فــا تعتدوهــا‪ ،‬ومــن يتعــد حــدود اهلل‬\n      ‫فأولئــك هــم الظاملــون»‪ ،‬واآليــة تقتضــي أن ال يتعــدى يف املقــدرات ال‬\n\n\n‫‪243‬‬\n\f                                                   ‫بزيــادة عليهــا وال نقصــان‪.‬‬\n‫‪ )9‬قــال ابــن قدامــة رحمــه اهلل تعالــى يف كتابــه املغنــي ‪ 74/9‬مــا‬\n‫نصــه‪« :‬مــا يوجــب احلــد مــن الزنــا والســرقة والقــذف وشــرب اخلمــر إذا‬\n‫تكــرر قبــل إقامــة احلــد أجــزأ حــد واحــد بغيــر خــاف علمنــاه‪ ،‬قــال‬\n‫ابــن املنــذر‪ :‬أجمــع علــى هــذا كل مــن نحفــظ عنــه مــن أهــل العلــم‪،‬‬\n‫منهــم عطــاء والزهــري ومالــك وأبــو حنيفــة وأحمــد وإســحاق وأبــو ثــور‬\n‫ومذهــب الشــافعي» أ‪.‬هــ‪ .‬فمــن بــاب أولــى أن التعازيــر تدخــل يف احلــدود‪،‬‬\n‫وللمتأمــل يف هــذه املســألة يتضــح لــه قــوة مــا اســتدل بــه أصحــاب القــول‬\n‫الثانــي‪ ،‬وقــوة ردودهــم علــى أدلــة أصحــاب القــول األول‪ ،‬ولــذا فاحلكــم‬\n‫علــى حالــه‪ ،‬وأمــرت بإحلــاق ذلــك بالقــرار‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/09/17‬ه ـ‬\n‫احلمــد هلل وحــده فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‪ 341645200‬وتاريــخ‬\n‫‪1434/10/18‬ه ـ واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫‪ .....‬برقم‪34253033‬وتاريــخ ‪1434/6/27‬ه ـ واخلــاص بدعــوى املدعــي‬\n‫العــام ضــد ‪ .....‬وموضوعهــا مســكر وبعــد التدقيــق يف إجابــة فضيلــة‬\n‫ناظــر القضيــة وفقــه اهلل علــى قــرار محكمــة االســتئناف الســابق تقــرر‬\n‫املصادقــة باألكثريــة علــى احلكــم لعــدم موجــب املالحظــة واهلل املوفــق‬\n                                          ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد ‪.‬‬\n\n\n\n\n                                                                                    ‫‪244‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":236,"source_page_end":244,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"14c44771b6de4eb4765befcc4885eb9f9c4009ee1d3761eb63c0c4d0212bdb6d","normalized_text_hash":"90fafe1a135d46b4e1897ca3c35ce40507d68b8bb3fb291125eb50a67029b6b2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p236-34253033"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

